(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0014.js"] = [{"id":"poem-5d7c909d0caeed84fa953b8b","title":"献砚诗","author":"方为","dynasty":"唐","verses":["金棱玉海比连城，假借文章取盛名。","（同前卷下。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-da63fe74-ed34-4012-ba4b-09c27fb3abaf","tags":[]},{"id":"poem-5d80fbabd00289028711e955","title":"羔羊","author":"佚名","dynasty":"先秦","verses":["羔羊之皮，素丝五紽。退食自公，委蛇委蛇。","羔羊之革，素丝五緎。委蛇委蛇，自公退食。","羔羊之缝，素丝五总。委蛇委蛇，退食自公。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-17","tags":[]},{"id":"poem-5d8cbb8b5531329c86231459","title":"一枝花","author":"无名氏《张协状元》","dynasty":"元","verses":["孩儿过来，试出幽闺，徐步花街。","(旦出)喜奴今日会开怀，是这花如锦，柳垂带。","(后净出合)穿红度绿，折朵奇葩带，奇葩带。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2719","tags":[]},{"id":"poem-5d96b19e67e6667afa4c4743","title":"及第后读书院咏物[一]十首上礼部李侍郎 滤水罗","author":"樊铸","dynasty":"唐","verses":["经纬既纵横，偏承启沃情。","含虚素心净，乐水智囊成。","密㥀（致）[一]能藏垢，疏通自去盈。","不问垂善滤，何问下流清。","（[一]余疑「㥀」是「致」通用俗字，或音误。","俞云：「校作『致』，较远，疑当作『慎』，因滤水罗正不必密致也。","密慎与下文疎通对文。","」按俞先生说较好。","刘校与俞同。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2ac80bef-9f79-40f7-8cda-37a53eef3a75","tags":[]},{"id":"poem-5da1e5b2daefdb3e863e638a","title":"郊庙歌辞 武后大享拜洛乐章 昭和","author":"不详","dynasty":"唐","verses":["舒阴致养，合大资生。","德以恒固，功由永贞。","升歌荐序，垂币翘诚。","虹开玉照，凤引金声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6a86c51e-e062-44b9-bf59-a3f54c997775","tags":[]},{"id":"poem-5da7a8dd3b6933a3bad427f7","title":"大·对宿烟收","author":"周邦彦","dynasty":"宋","verses":["对宿烟收，春禽静，飞雨时鸣高屋。","墙头青玉旆，洗铅霜都尽，嫩梢相触。","润逼琴丝，寒侵枕障，虫网吹沾帘竹。","邮亭无人处，听檐声不断，困眠初熟。","奈愁极顿惊，梦轻难记，自怜幽独。","行人归意速。","最先念、流潦妨车毂。","怎奈向、兰成憔悴，卫清羸，等闲时、易伤心目。","未怪平阳客，双泪落、笛中哀曲。","况萧索、青芜国。","红糁铺地，门外荆桃如菽。","夜游共谁秉烛。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-234","tags":["宋词三百首"]},{"id":"poem-5daa34d056b365913037c9c7","title":"阮郎归·江南江北雪漫漫","author":"向子𬤇","dynasty":"宋","verses":["江南江北雪漫漫。","遥知易水寒。","同云深处望三关。","断肠山又山。","天可老，海能翻。","消除此恨难。","频闻遣使问平安。","几时鸾辂还。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-114","tags":[]},{"id":"poem-5db8c233bd1a197b920e475f","title":"蝶恋花·卷絮风头寒欲尽","author":"晏几道","dynasty":"宋","verses":["卷絮风头寒欲尽。","坠粉飘红，日日香成阵。","新酒又添残酒困。","今春不减前春恨。","蝶去莺飞无处问。","隔水高楼，望断双鱼信。","恼乱层波横一寸。","斜阳只与黄昏近。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-20","tags":["宋词三百首"]},{"id":"poem-5dbb71073a5db9ae79507769","title":"与峨眉山道士期尽日不至","author":"鲍溶","dynasty":"唐","verses":["倾景安再中，人生有何常。","胡为少君别，风驭峨眉阳。","结我千日期，青山故人堂。","期尽师不至，望云空烧香。","顾慙有限身，易老白日光。","怀君屡惊叹，支体安能强。","往闻清修箓，未究服食方。","瑶田有灵芝，眼见不得尝。","玉壶贮天地，岁月亦已长。","若用壶中景，东溟又堪伤。","寄言赤玉箫，夜夜吹清商。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f78fd453-41dc-47cb-adaa-c2c86dde0f7b","tags":[]},{"id":"poem-5dbd991f77104e4fedd4e807","title":"赠长安毕郎中","author":"李洞","dynasty":"唐","verses":["高门寒沼水连云，鹭识朱衣傍主人。","地肺半边晴带雪，天街一面静无尘。","朝回座客酬琴价，衙退留僧写鹤真。","从此几迁为计相，蓬莱三刻奏东巡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ee20475d-7930-43dd-9451-d3afdb00910b","tags":[]},{"id":"poem-5dc646cf3f90e60d5e7e5272","title":"木兰花・玉楼春·溶溶水映娟娟秀","author":"方千里","dynasty":"宋","verses":["溶溶水映娟娟秀。","浅约宫妆笼翠袖。","舞馀杨柳乍萦风，睡起海棠犹带酒。","憔悴萧郎缘底瘦。","那日花前相见后。","西窗疑是故人来，费得罗笺诗几首。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-530","tags":[]},{"id":"poem-5dcd9ee7d8b91d2c3de78194","title":"闻王慥常侍卒三首 二","author":"贯休","dynasty":"唐","verses":["宗社运微衰，山摧甘井枯。","不知千载后，更有此人无。","政入龚黄甲，诗轻沈宋徒。","受恩酬未得，不觉祗长吁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5fbe45d0-4760-4422-87b2-96df7becce86","tags":[]},{"id":"poem-5dceca78a3e95066e74e022d","title":"北山","author":"王安石","dynasty":"宋","verses":["北山输绿涨横陂，直堑回塘滟滟时。","细数落花因坐久，缓寻芳草得归迟。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-北山","tags":[]},{"id":"poem-5dd6172792afce4888357d04","title":"古塞曲三首 三","author":"贯休","dynasty":"唐","verses":["百万精兵动，参差便渡辽。","如何好白日，亦照此天骄。","远树深疑贼，惊蓬迥似雕。","凯歌何日唱，碛路共天遥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d71efae1-1556-4efc-83e4-500de066aa44","tags":[]},{"id":"poem-5dd7d30c6358c4d8ed948e00","title":"南园十三首 三","author":"李贺","dynasty":"唐","verses":["竹里缲丝挑网车，青蝉独噪日光斜。","桃胶迎夏香琥珀，自课越佣能种瓜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-21e0b774-e999-4b7a-9e1d-25160d5398c8","tags":[]},{"id":"poem-5de2d099bdbb2515c8ee0d1f","title":"题张于潜画轴五首  其二","author":"释居简","dynasty":"宋","verses":["昭阳燕子一双飞，涎涎随风懒哺儿。","可是刘郎无酝藉，不教嫔御读周诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-e7760ee3-0526-4546-881a-6cf83cee797d","tags":[]},{"id":"poem-5df708e71cc99b66eb2cc36d","title":"至七里滩作","author":"李嘉祐","dynasty":"唐","verses":["迁客投于越，临江泪满衣。","独随流水远，转觉故人稀。","万木迎秋序，千峰驻晚晖。","行舟犹未已，惆怅暮潮归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-90852836-e7f5-4e1f-87d7-5961625496ad","tags":[]},{"id":"poem-5dfb2f49efde68b585dbe90d","title":"中山别墅","author":"俞瑊","dynasty":"宋","verses":["村居何所乐，我爱读书堂。","阶草侵窗润，瓶花落砚香。","凭栏看水活，出岫笑云忙。","野客时相过，联吟坐夕阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-55dfe7ab-c108-40b2-aa21-217cbbee5024","tags":[]},{"id":"poem-5dff6a3ef7dd9da19f674650","title":"生日  其二","author":"孙嵩","dynasty":"宋","verses":["鸿雁关河秋满眼，梧桐风雨冷吹衣。","蓼莪自是长休废，独立苍苔一叹欷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-afb93102-f324-4ee7-8427-35868f559f45","tags":[]},{"id":"poem-5e1141d4b6bdaf3824865a1d","title":"偶然五首 二","author":"皎然","dynasty":"唐","verses":["偶然寂无喧，吾了心性源。","可嫌虫食木，不笑鸟能言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3879732f-c0c2-47a0-9fa3-b0a206bdbc89","tags":[]},{"id":"poem-5e13a304a0636d9b2fe628db","title":"大夫松","author":"徐夤","dynasty":"唐","verses":["五树旌封许岁寒，挽柯攀叶也无端。","争如涧底凌霜节，不受秦皇乱世官。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3a4ee675-2158-4a82-a8ba-0b922b96f20c","tags":[]},{"id":"poem-5e1a1e94cd2bbe81f6ce3de4","title":"省题诗二十一首 咏白","author":"王棨","dynasty":"唐","verses":["非青玄赤黄，正色配金方。","鱼表周王德，麟呈汉帝祥。","寒来边草远，春至岭梅芳。","曳练闻良马，衔钩见瑞狼。","张苍肥似瓠，潘岳鬓如霜。","虚室能生后，方知守黑长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-569c3ddd-64e4-4e8d-8848-e65dd8c24078","tags":[]},{"id":"poem-5e1ccea1e36b5075fce2b483","title":"酒泉子·雨渍花零","author":"李珣","dynasty":"五代","verses":["雨渍花零，红散香凋池两岸。","别情遥，春歌断，掩银屏。","孤帆早晚离三楚，闲理钿筝愁几许？","曲中情，弦上语，不堪听。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-38","tags":[]},{"id":"poem-5e2a9e0ae14efbd7d9660dac","title":"观郑州崔郎中诸妓绣样","author":"胡令能","dynasty":"唐","verses":["日暮堂前花蘂娇，争拈小笔上床描。","绣成安向春园里，引得黄莺下柳条。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c740ff6c-2a8d-4d11-9a7e-9e699c7c7998","tags":[]},{"id":"poem-5e3d18e9a66c48ac6453491e","title":"太平坊寻裴郎中故宅","author":"子兰","dynasty":"唐","verses":["不语凄凉无限情，荒堦行尽又重行。","昔年住此何人在，满地槐花秋草生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-12d0306e-9266-438c-af72-21161bea05fb","tags":[]},{"id":"poem-5e46fd56644d067a64bd4ecc","title":"桑中","author":"佚名","dynasty":"先秦","verses":["爰采唐矣？沬之乡矣。云谁之思？美孟姜矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。","爰采麦矣？沬之北矣。云谁之思？美孟弋矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。","爰采葑矣？沬之东矣。云谁之思？美孟庸矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-47","tags":[]},{"id":"poem-5e4b9c872ad713b8655cc59e","title":"题榴花","author":"朱熹","dynasty":"宋","verses":["五月榴花照眼明，枝间时见子初成。","可怜此地无车马，颠倒苍苔落绛英。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題榴花","tags":[]},{"id":"poem-5e53bbf55f24f97c52eafd57","title":"羔裘","author":"佚名","dynasty":"先秦","verses":["羔裘如濡，洵直且侯。彼其之子，舍命不渝。","羔裘豹饰，孔武有力。彼其之子，邦之司直。","羔裘晏兮，三英粲兮。彼其之子，邦之彦兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-79","tags":[]},{"id":"poem-5e547d6c76ffdde55b61a8af","title":"补迎神奏永和之舞九变第二奏","author":"陈致雍","dynasty":"唐","verses":["说祝于室，焫萧燃脂。","几筵斯设，妥以皇诗。","云韶清越，绛服离披。","僾然如此，永感孝思。","（《大唐郊祀录》卷九）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-79dddbf0-eed5-4ccb-9afa-ecb15eba81c8","tags":[]},{"id":"poem-5e591da1429c77862edf4d04","title":"扑灯蛾","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生)打伊泼丑生，怎敢到此处！恶向胆边生，教人怒从心起也。","(小生)适来路里，见吾兄倒在街衢。","是孙荣背负你归，多谢得贤达嫂嫂留住赐乞食。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1777","tags":[]},{"id":"poem-5e5c411ff2885d93d3b8ff0c","title":"永明山居诗（六十九首） 六十九","author":"延寿","dynasty":"唐","verses":["三度曾经游此地，从缘权顺世间情。","登山虽有谢安志，遁迹惭无慧远名。","翠叠寒枝松未老，影深幽径竹新成。","莫言去住关怀抱，云本无心水自清。","（见忏庵居士《高僧山居诗》，上海商务印书馆民国二十三年线装铅印本。","）（〖1〗张靖龙云：永明即延寿。","清释际祥《净慈寺志》〖《武林掌故丛编》第十三集〗卷十九附著述目中有「《永明寿禅师山居诗》，吴越僧延寿撰」等语。","卷十八明人李日华山居诗序中记载了永明山居诗的刻本来源，序后附录佛国山人黄树谷《集山居诗绝句》十首。","旁小字注曰：「集永明寿禅师诗句。","」其词句与忏庵居士本全部相同。","集句诗后附载和诗诸公云，高峰妙法嗣布衲雍公，尝居南屏，赓和《永明山居诗》六十九首，楚石梵琦有《和永明山居诗》，梅雪有《和永明山居诗》。","古春云：「永明寿禅师有诗六十九首，庆寿独庵从和之。","」按元代天目山大觉正等寺布衲祖雍的和作，今存其一，见《西天目祖山志》卷五，步延寿山居诗其二韵。","又忏庵居士《高僧山居诗续编》载元代天台高僧无见先覩《和永明禅师〖山居诗〗韵》六十九首，步韵甚严。","从永明山居诗的内容来看，也属智觉延寿所作无疑。","详细考证参见拙作《延寿及其佚诗》，载《温州师专学报》〖社会科学版〗一九八六年第三期。","按：日本《续藏经》本宋释文冲《慧日永明寺智觉禅师自行录》末附延寿著作总目，有《山居诗》一卷，当即指以上所录诸诗。","此书所录延寿所作诗尚有《诗赞》一卷、《物外集》十卷五百首、《吴越唱和诗》一卷、《光明会瑞应诗》一卷、《供养石桥罗汉一十会祥瑞诗》一卷、《杂歌》一卷、《布金歌》一卷、《定慧相资歌》一卷。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-036c0045-3116-4c82-ac11-2b71804e09fd","tags":[]},{"id":"poem-5e7088bec31edad83071a85d","title":"遵大路","author":"佚名","dynasty":"先秦","verses":["遵大路兮，掺执子之袪兮。无我恶兮，不蓵故也！","遵大路兮，掺执子之手兮。无我魗兮，不蓵好也！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-80","tags":[]},{"id":"poem-5e70e492bd95f237b5d20427","title":"驺虞","author":"佚名","dynasty":"先秦","verses":["彼茁者葭，壹发五豝，于嗟乎驺虞！","彼茁者蓬，壹发五豵，于嗟乎驺虞！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-24","tags":[]},{"id":"poem-5e81076d0186321713dd9f4d","title":"荷叶杯·镜水夜来秋月","author":"温庭筠","dynasty":"唐","verses":["镜水夜来秋月，如雪。采莲时。","小娘红粉对寒浪，惆怅。正思惟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-14","tags":[]},{"id":"poem-5e881345e81f14f15fa4a8cb","title":"最后颂（一作「语」）","author":"智闲","dynasty":"唐","verses":["有一语，全规矩，休思量（一作「惟」），不自许。","路逢同（一作「达」）道人，杨眉省来处。","踏不著，多疑虑，却思量（一作「看」），带伴侣。","一生参学事无成，慇懃抱得栴檀树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-144cd2bf-a39d-43f5-a228-929e21fbee64","tags":[]},{"id":"poem-5e8f28a1e8f0c581c66280f6","title":"浣溪沙·湖上西风急暮蝉","author":"晏殊","dynasty":"宋","verses":["湖上西风急暮蝉。","夜来清露湿红莲。","少留归骑促歌筵。","为别莫辞金盏酒，入朝须近玉炉烟。","不知重会是何年。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-441","tags":[]},{"id":"poem-5e91c150a75b9aad205bbc52","title":"赠天台僧","author":"江为","dynasty":"唐","verses":["白发经年复白眉，斋身多病已无机。","曾来越客留诗板，旧识蕃人送衲衣。","岩窦夜禅云树湿，石桥秋望海山微。","结庵更拟寻华顶，晚岁应容叩竹扉。","（见《四库珍本初集》本宋林师蒧《天台续集》卷下。","）（按：《天台续集》二卷，为林师蒧据宋李庚原本编成，所收「皆宋初迄宣、政间人之诗」〖《四库全书总目》卷一八七〗，清陆心源《宋诗纪事补遗》卷四因据以录入。","其实，江为幷未入宋。","陶岳《五代史补》卷五、龙衮《江南野录》卷八、马令《南唐书》卷十四、陆游《南唐书》卷十二、吴任臣《十国春秋》卷九七所载为传，均云为于南唐元宗时因事被诛。","其时宋尚未立国，作宋诗未当。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-df7d9c93-a855-4b05-9ac5-4d35647c1cc8","tags":[]},{"id":"poem-5e9ed48b5b661ad4c866b399","title":"探春令","author":"刘唐卿《白兔记》","dynasty":"元","verses":["彤云缭绕，六花飞遍，楼台银砌。","拥红炉，添兽炭，犹嫌冷。","看贫者谁肯相怜？尽道丰年瑞，丰年瑞若何？长安有贫者，宜瑞不宜多。","奴家岳氏秀英，不免上层楼上，做些女工针指。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8907","tags":[]},{"id":"poem-5e9fdd5d33f01ec7460bfe24","title":"春风","author":"李咸用","dynasty":"唐","verses":["青帝使和气，吹嘘万国中。","发生宁有异，先后自难同。","辇草不消力，岩花应费功。","年年三十骑，飘入玉蟾宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-06274f5a-bc41-4b8a-9f97-645a16336434","tags":[]},{"id":"poem-5ea7810451ac5f69bf519974","title":"送铜泽王归城","author":"李端","dynasty":"唐","verses":["昔闻公族出，其从亦高车。","为善唯求乐，分贫必及疎。","身承汉枝叶，手习鲁诗书。","尚说无功德，三年在石渠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ae54e684-8316-4298-b04d-1ad47322262b","tags":[]},{"id":"poem-5eb2215a136cc7a454946162","title":"永遇乐·落日熔金","author":"李清照","dynasty":"宋","verses":["落日熔金，暮云合璧，人在何处。","染柳烟浓，吹梅笛怨，春意知几许。","元宵佳节，融和天气，次第岂无风雨。","来相召、香车宝马，谢他酒朋诗侣。","中州盛日，闺门多暇，记得偏重三五。","铺翠冠儿，拈金雪柳，簇带争济楚。","如今憔悴，风鬟霜鬓，怕见夜间出去。","不如向、帘儿底下，听人笑语。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-203","tags":["宋词三百首"]},{"id":"poem-5ecbca53eef777aff532d116","title":"即事寄人","author":"杨凌","dynasty":"唐","verses":["中禁鸣钟日欲高，北窗欹枕望频搔。","相思寂寞青苔合，唯有春风啼伯劳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d98880f6-8f83-4a02-9fc7-94dca8c9fed9","tags":[]},{"id":"poem-5ecc2e0fa63485f815e897d9","title":"寓郁林著易传有感  其二","author":"李纲","dynasty":"宋","verses":["羲文作易仲尼传，究极阴阳本自然。","妙理欲求须得象，至言已契可忘筌。","绝编何啻须三过，知命从今加数年。","叹息时无邵康节，数该今古与谁研。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4e4fb1c0-35ef-420a-acc9-8734e059eff4","tags":[]},{"id":"poem-5ed0d326b99e3296e1b1c622","title":"留别阎士和","author":"皎然","dynasty":"唐","verses":["不惯人间别，多应忘别时。","逢山又逢水，只畏却来迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a2c15180-6f0d-4087-934d-79fd364e25b9","tags":[]},{"id":"poem-5ed5322b21c6deb74e99a8ab","title":"菩萨蛮·银潢清浅填乌鹊","author":"陈师道","dynasty":"宋","verses":["银潢清浅填乌鹊。","画檐急雨长河落。","初月未成圆。","明星惜此筵。","愁来无断绝。","岁岁年年别。","不用泪红滋。","年年岁岁期。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-294","tags":[]},{"id":"poem-5ed9592733c114a1718430f3","title":"句","author":"崔建","dynasty":"唐","verses":["回风向晓平湖上，引得荷花隔浦香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-620b6c6f-f5d3-40c0-8cba-55700cfb53cd","tags":[]},{"id":"poem-5eda4f91333a38cc4c01f892","title":"南乡子·何处可魂消","author":"张先","dynasty":"宋","verses":["何处可魂消。","京口终朝两信潮。","不管离心千叠恨，滔滔。","催促行人动去桡。","记得旧江皋。","绿杨轻絮几条条。","春水一篙残照阔，遥遥。","有个多情立画桥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-264","tags":[]},{"id":"poem-5ee9034bfcb1a231c5e9a82e","title":"表兄话旧","author":"窦叔向","dynasty":"唐","verses":["夜合花开香满庭，夜深微雨醉初醒。","远书珍重何由达，旧事凄凉不可听。","去日儿童皆长大，昔年亲友半凋零。","明朝又是孤舟别，愁见河桥酒幔青。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-表兄話舊","tags":[]},{"id":"poem-5eedbd56368226cd8bffa785","title":"寻桃源","author":"张乔","dynasty":"唐","verses":["武林春草齐，花影隔澄溪。","路远无人去，山空有鸟啼。","水垂青霭断，松偃绿萝低。","世上迷途客，经兹尽不迷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-51a4c495-3f07-4d11-b30a-5ccfc6210734","tags":[]},{"id":"poem-5eefb1ef6166e4288c2e8c65","title":"少年游·玉壶冰莹兽炉灰","author":"欧阳修","dynasty":"宋","verses":["玉壶冰莹兽炉灰。","人起绣帘开。","春从一夜，六花开尽，不待剪刀催。","洛阳城阙中天起，高下遍楼台。","絮乱风轻，拂鞍沾袖，归路似章街。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-767","tags":[]},{"id":"poem-5ef07fb71765c0134af18db2","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)潜观慈母两眉攒，他欢无半点，愁有千般。","朝夕萦绊，教人痛苦针钻。","(净)河伯水官，那其间怎把人勾唤？致令得死别生离，如何会意悦心欢？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8289","tags":[]},{"id":"poem-5efbe02af43d450d20cbdd69","title":"感皇恩","author":"杨景贤","dynasty":"元","verses":["呀！遮莫你竹杖龙飞，华表鹤归。","恋荣辱有灾危，远是非无挂念，叹生死有迟疾。","你若要西天取经，先去这东土忘机，参菩萨，拜圣贤，礼摩尼。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10316","tags":[]},{"id":"poem-5efd2d67d83d02bed6a7ae6e","title":"秋夕","author":"杜牧","dynasty":"唐","verses":["银烛秋光冷画屏，轻罗小扇扑流萤。","天街夜色凉如水，卧看牵牛织女星。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋夕","tags":[]},{"id":"poem-5f0240878c2589185170f5f6","title":"立秋","author":"刘翰","dynasty":"宋","verses":["乳鸦啼散玉屏空，一枕新凉一扇风。","睡起秋声无觅处，满阶梧叶月明中。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-立秋","tags":[]},{"id":"poem-5f0af0505c7e0d6f676541e9","title":"捣练子·红粉里","author":"李石","dynasty":"宋","verses":["红粉里，绛金裳。","一卮仙酒艳晨妆。","醉温柔，别有乡。","清暑殿，藕风凉。","鸡头擘破误君王。","泣梨花，春梦长。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-281","tags":[]},{"id":"poem-5f172dd9b07c435bfa6aded0","title":"昔年二首  其一","author":"赵文","dynasty":"宋","verses":["昔年携汝赴闽京，此日深儿尚未生。","今日携儿收叔骨，一如当日共伊行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8ea5c5f0-344a-46a7-b69f-84359eddf5a1","tags":[]},{"id":"poem-5f1afb9cb486ef01525a9c29","title":"灞上逢故人","author":"喻坦之","dynasty":"唐","verses":["花落杏园枝，驱车问路岐。","人情谁可会，身事自堪疑。","岳雨狂雷送，溪槎涨水吹。","家山如此景，几处不相随。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2064ae72-e606-4bbb-88e8-31e61194cadc","tags":[]},{"id":"poem-5f1c5ce4efb994acbbc54efc","title":"唐享昊天乐 第九","author":"则天皇后","dynasty":"唐","verses":["荷恩承顾托，执契恭临抚。","庙略静边荒，天兵曜神武。","有截资先化，无为遵旧矩。","祯符降昊穹，大业光寰宇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-20970cd3-7041-486e-b7b5-3ec719f181b3","tags":[]},{"id":"poem-5f26a136c17ae902def766d3","title":"古意九首 六","author":"贯休","dynasty":"唐","verses":["古交如真金，百炼色不回。","今交如暴流，儵忽生尘埃。","我愿君子气，散为青松栽。","我恐荆棘花，只为小人开。","伤心复伤心，吟上高高台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0cdc8483-10f9-43d1-a125-e400ac468bf6","tags":[]},{"id":"poem-5f383010b6c5b9bb2f01dc06","title":"句","author":"戴之邵","dynasty":"宋","verses":["愁绝江梅开岭岸，不知失脚到南塘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a450ef49-ae22-450b-b22f-dbe13230d3e0","tags":[]},{"id":"poem-5f431cfacf692417955a2069","title":"广教不厌亭","author":"释居简","dynasty":"宋","verses":["眼挂层峦醉益青，旋疑身是出山云。","一泉一石忘情地，都作鸿沟与俗分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-ca683871-be72-4ce1-bbd2-7ca39544a173","tags":[]},{"id":"poem-5f440f6cdc3d09d8140ec31d","title":"古北口","author":"纳兰性德","dynasty":"清","verses":["乱山入戟拥孤城，一线人争鸟道行。","地险东西分障塞，云开南北望神京。","新图已入三关志，往事休论十路兵。","都护近来长不调，年年烽火报生平。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-231","tags":[]},{"id":"poem-5f478c38bc3f21cf72b002e0","title":"别段生","author":"张籍","dynasty":"唐","verses":["与子骨肉亲，愿言长相随。","况离父母傍，从我学书诗。","同在道路间，讲论亦未亏。","为文于我前，日夕生光仪。","行役多疾疚，赖此相扶持。","贫贱事难拘，今日有别离。","我去秦城中，子留汴水湄。","离情两飘断，不异风中丝。","幼年独为客，举动难得宜。","努力自修励，常如见我时。","送我登山冈，再拜问还期。","还期在新年，勿怨欢会迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-738d2629-b1b5-4688-bca6-bee1805a13fb","tags":[]},{"id":"poem-5f47a23a1d753765f2d090ea","title":"杏殇 七","author":"孟郊","dynasty":"唐","verses":["哭此不成春，泪痕三四斑。","失芳蝶既狂，失子老亦孱。","且无生生力，自有死死颜。","灵凤不衔诉，谁为扣天关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-22024e09-ca03-4c28-a9c9-9cc3f7a12281","tags":[]},{"id":"poem-5f4a0e4ac6e4ef2f7bc90b0c","title":"皇皇者华","author":"佚名","dynasty":"先秦","verses":["皇皇者华，于彼原隰。𬳽𬳽征夫，每怀靡及。","我马维驹，六辔如濡。载驰载驱，周爰咨诹。","我马维骐，六辔如丝。载驰载驱，周爰咨谋。","我马维骆，六辔沃若。载驰载驱，周爰咨度。","我马维骃，六辔既均。载驰载驱，周爰咨询。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-162","tags":[]},{"id":"poem-5f53b26adfc932b85ecddbf3","title":"失调名·犹将歌扇向人遮","author":"李清照","dynasty":"宋","verses":["犹将歌扇向人遮。","水晶山枕象牙床。","彩云易散月长亏。","几多深恨断人肠。","罗衣消尽恁时香。","闲愁也似月明多。","直送凄凉到画屏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-704","tags":[]},{"id":"poem-5f5eb2b83ec85c0aa0d4d866","title":"醉花阴·池面芙蕖红散绮","author":"李弥逊","dynasty":"宋","verses":["池面芙蕖红散绮。","鹊噪朱门喜。","环佩响天风，香霭杯盘，更约麻姑侍。","尘寰不隔蓬莱水。","束带岩廊戏。","瘦鹤与长松，且伴臞仙，久住人间世。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-43","tags":[]},{"id":"poem-5f65907dc793928efb96af64","title":"书梅福殿壁二首 二","author":"张乔","dynasty":"唐","verses":["一自白云去，千秋坛月明。","我来思往事，谁更得长生。","雅韵磬钟远，真风楼殿清。","今来为尉者，天下有仙名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-36d31cf8-16e6-4ade-91f6-4549375ac632","tags":[]},{"id":"poem-5f69b895f7f5c7b19f445c22","title":"送房明府罢长宁令湖州客舍","author":"李嘉祐","dynasty":"唐","verses":["君为万里宰，恩及五湖人。","未满先求退，归闲不厌贫。","远峰晴更近，残柳雨还新。","要自趋丹陛，明年鸡树亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d4964360-04be-4cde-a26a-df00ee1f498c","tags":[]},{"id":"poem-5f6b56267410124258b6fc26","title":"秋夜","author":"王镃","dynasty":"宋","verses":["桂香吹老月中秋，人在西风雁过楼。","半夜枕寒清梦断，银河影挂玉帘钩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-daa9128d-6b5c-44ce-91ad-50a6ebece6eb","tags":[]},{"id":"poem-5f77e7ce433e048fae7b8db5","title":"雪夜二首  其二","author":"王镃","dynasty":"宋","verses":["落在空中似雨飞，成花因被紧风吹。","销金帐掩红娇处，暖护歌声醉不知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b490fc0b-fbd7-4fee-8580-6ca2bcca245b","tags":[]},{"id":"poem-5f7905cc46ff67020d1080ca","title":"相思儿令·昨日探春消息","author":"晏殊","dynasty":"宋","verses":["昨日探春消息，湖上绿波平。","无奈绕堤芳草，还向旧痕生。","有酒且醉瑶觥。","更何妨、檀板新声。","谁教杨柳千丝，就中牵系人情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-546","tags":[]},{"id":"poem-5f819d41c6e9614eac11a662","title":"送商季臯","author":"皎然","dynasty":"唐","verses":["比来知尔有诗名，莫恨东归学未成。","新丰有酒为我饮，消取故园伤别情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d95317f6-6e5d-4942-b589-01c5468f332f","tags":[]},{"id":"poem-5f85c7cc458d5a73ee8008dd","title":"寄严文炳  其六","author":"陈造","dynasty":"宋","verses":["善忘常憎医，独者自尊足。","严子肮脏面，如我不谐俗。","世情趣操间，憎爱岐珉玉。","饶舌夸我贤，祗取白眼辱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a53b4943-78e7-4e47-aa92-50ba6f9e7259","tags":[]},{"id":"poem-5f89b50576f5a91537f8be21","title":"蓦山溪·疏梅雪里","author":"蔡伸","dynasty":"宋","verses":["疏梅雪里，已报东君信。","冷艳与清香，似一个、人人标韵。","晚来特地，酌酒慰幽芳，携素手，摘纤枝，插向乌云鬓。","老来世事，百种皆消尽。","荣利等浮云，谩汲汲、徒劳方寸。","花前眼底，幸有赏心人，歌金缕，醉瑶卮，此外君休问。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-930","tags":[]},{"id":"poem-5f9086956dfb4d86564b6972","title":"天宝禁中","author":"赵崇嶓","dynasty":"宋","verses":["外庭班退寿王归，别有骄儿侍禁闱。","解事老奴宁及远，君恩如许政忘机。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1af2473a-e9c2-4819-ba0a-482be3e88d4d","tags":[]},{"id":"poem-5f932bac7676b609a992a804","title":"郊庙歌辞 享太庙乐章 同和","author":"不详","dynasty":"唐","verses":["惟圣配天敷盛礼，惟天为大阐洪名。","恭禋展敬光先德，苹藻申虔表志诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2e25e2a4-0a40-4306-86dd-43430565e2b5","tags":[]},{"id":"poem-5f96007136f49e8c3b83b3ca","title":"孤山彭高士借榻","author":"释居简","dynasty":"宋","verses":["万籁笙镛一枕秋，幌云垂地月痕收。","偶然做得还乡梦，梦见鸿蒙与道游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f69e86db-56fe-49f6-b992-0a0514d04320","tags":[]},{"id":"poem-5f96469f159bf73caa2db6b0","title":"山中避难作","author":"来鹄","dynasty":"唐","verses":["山头烽火水边营，鬼哭人悲夜夜声。","唯有碧天无一事，日还西下月还明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-75dd09a5-71b9-47d8-9f49-593cfed39750","tags":[]},{"id":"poem-5fa1ca27a412272f98bda736","title":"偈","author":"善道","dynasty":"唐","verses":["南山路仄（《五灯会元》作「侧」）东山低（《祖庭事苑》作「东山路侧西山低」），新到莫辞三转（一作「担」）泥。","嗟汝在途经日久，明明不晓（《祖庭事苑》作「向道」）却成迷。","（见《景德传灯录》卷二十、《五灯会元》卷六《祖庭事苑》卷二。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1791761c-01e4-4226-bd3e-b7e20ee8420e","tags":[]},{"id":"poem-5fa22c60879d41a12dafde3f","title":"陆别驾解组","author":"释居简","dynasty":"宋","verses":["不平容赴愬，无枉不相关。","契托今州牧，官同旧笋班。","骚情吟未尽，乐府载将还。","况是平分手，新声课小蛮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-e0fd6eec-b894-4a63-bff1-3804a66f5abe","tags":[]},{"id":"poem-5fad29a19745eb94db6e51ea","title":"秦筝怨（伯三八八五）","author":"宋家娘子","dynasty":"唐","verses":["玳瑁秦筝里，声声怨别离。","只缘多苦调，欲奏泪还垂。","妾意如弦直，君心学柱移。","𫏐时停不弄，音调早参差。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c987e46b-4ec1-40ae-a454-553d40735424","tags":[]},{"id":"poem-5fb270d7b393f91404b78dc6","title":"摊声浣溪沙・浣溪沙·雨色流香绕坐中","author":"毛滂","dynasty":"宋","verses":["雨色流香绕坐中。","映阶疏竹一丛丛。","不奈晚来萧瑟意，子猷风。","潋滟满倾金凿落，淋漓从湿绣芙蓉。","吸尽百川天上去，看长虹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-756","tags":[]},{"id":"poem-5fb38d9bcd6a16d096a2a657","title":"瑞鹤仙·脸霞红印枕","author":"陆淞","dynasty":"宋","verses":["脸霞红印枕。","睡觉来、冠儿还是不整。","屏间麝煤冷。","但眉峰压翠，泪珠弹粉。","堂深昼永。","燕交飞、风帘露井。","恨无人，与说相思，近日带围宽尽。","重省。","残灯朱幌，淡月纱窗，那时风景。","阳台路迥。","云雨梦，便无准。","待归来，先指花梢教看，却把心期细问。","问因循、过了青春，怎生意稳。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-101","tags":["宋词三百首"]},{"id":"poem-5fbde247b9f66c083068e7df","title":"燕","author":"徐夤","dynasty":"唐","verses":["从待衔泥溅客衣，百禽灵性比他稀。","何嫌何恨秋须去，无约无期春自归。","雕鹗不容应不怪，栋梁相庇愿相依。","吴王宫女娇相袭，合整双毛预奋飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7e90f29e-1ec0-4b6f-b0b5-27b6fe4838d6","tags":[]},{"id":"poem-5fc565a0696e60641e45a46e","title":"罗道士","author":"张籍","dynasty":"唐","verses":["城里无人得实年，衣襟常带臭黄烟。","楼中赊酒唯留药，洞里争棋不赌钱。","闻客语声知贵贱，持花歌咏似狂颠。","寻常行处皆逢见，世上多疑是谪仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-bb9157d6-9cc6-42ff-8fb0-b59181af7aba","tags":[]},{"id":"poem-5fd66f52e48075e8931ea81c","title":"伤韦令孔雀词","author":"王建","dynasty":"唐","verses":["可怜孔雀初得时，美人为尔别开池。","池边凤凰作伴侣，羌声鹦鹉无言语。","雕笼玉架嫌不栖，夜夜思归向南舞。","如今憔悴人见恶，万里更求新孔雀。","热眠雨水饥拾虫，翠尾盘泥金彩落。","多时人养不解飞，海山风黑何处归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ddec6ff9-8dd4-4e9e-8789-009f896a7703","tags":[]},{"id":"poem-5fe27e046b560fae6e251634","title":"和子华游君贶园  其二","author":"司马光","dynasty":"宋","verses":["小桃似喜相君来，争发新花继落梅。","更仗环溪醒残酒，没篙春水绿于苔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e594403f-015c-4a16-a5d6-16066ee5c06f","tags":[]},{"id":"poem-5fe3c4b336d56125528c1d52","title":"上黄堆烽","author":"李益","dynasty":"唐","verses":["心期紫阁山中月，身过黄堆烽上云。","年发已从书劒老，戎衣更逐霍将军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c3a17902-eb44-4244-9cd8-d60a4ac55f82","tags":[]},{"id":"poem-5fe42a08fd71bca65f98fd26","title":"翡翠岩","author":"赵嘏","dynasty":"唐","verses":["芙蓉幕里千场醉，翡翠岩前半日闲。","惆怅晋朝人不到，谢公抛力上东山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-40b14c6a-1ee6-4703-ba08-780fa7d023b9","tags":[]},{"id":"poem-5ff05163138557a65a039d43","title":"梦泽中行","author":"孟郊","dynasty":"唐","verses":["楚山争蔽亏，日月无全辉。","楚路饶回惑，旅人有迷归。","骐骥思北首，鹧鸪愿南飞。","我怀京洛游，未厌风尘衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d9ac40a0-4639-4fcb-9520-7aecd5d4c9e6","tags":[]},{"id":"poem-5ff2a5ef7de06988be63f4b0","title":"送碁待诏朴球归新罗","author":"张乔","dynasty":"唐","verses":["海东谁敌手，归去道应孤。","阙下传新势，船中覆旧图。","穷荒回日月，积水载寰区。","故国多年别，桑田复在无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e764782e-ad6a-4609-a0b2-ca8a5f877f59","tags":[]},{"id":"poem-5ff6491a8419ad600b4ccd5d","title":"怀古呈通守郑定斋  其四","author":"王柏","dynasty":"宋","verses":["北方有大井，深潜几万寻。","煎为东阿胶，莹彻如球琳。","持此一寸微，可救千丈浑。","世道一以浊，贪风方襄陵。","谁能汲此水，净涤四海心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f02316c5-7a5c-4f71-9166-464b397d73a2","tags":[]},{"id":"poem-60042a1c27dbe6ce52b1605d","title":"上冯使君五首 一","author":"贯休","dynasty":"唐","verses":["撑船碧江上，春日何迟迟。","汀花最深处，拾得鸳鸯儿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-42d13e43-6efe-4101-bf30-8685ef9c5cbd","tags":[]},{"id":"poem-6006f3e3655bf66e895451f6","title":"吊卢殷 一","author":"孟郊","dynasty":"唐","verses":["诗人多清峭，饿死抱空山。","白云既无主，飞出意等闲。","久病床席尸，护丧童仆孱。","故书穷鼠啮，狼藉一室间。","君归新鬼乡，我面古玉颜。","羞见入地时，无人叫追攀。","百泉空相吊，日久哀潺潺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-de14bb60-1d94-446e-afff-0c7d17b454d4","tags":[]},{"id":"poem-600d9ef8c1d4cccf9eb31453","title":"祝英台近·翦红情","author":"吴文英","dynasty":"宋","verses":["翦红情，裁绿意，花信上钗股。","残日东风，不放岁华去。","有人添烛西窗，不眠侵晓，笑声转、新年莺语。","旧尊俎。","玉纤曾擘黄柑，柔香系幽素。","归梦湖边，还迷镜中路。","可怜千点吴霜，寒销不尽，又相对、落梅如雨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-196","tags":["宋词三百首"]},{"id":"poem-600f5ccd1ec2ebf29d2ab5ae","title":"狂题十八首 十一","author":"司空图","dynasty":"唐","verses":["初时拄杖向邻村，渐到清明亦杜门。","三十年来辞病表，今朝卧病感皇恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8efe24b3-cd66-4fd4-8925-832d6547bf14","tags":[]},{"id":"poem-601b11f8b8d773de4cfc134a","title":"长相思·沙棠舟","author":"周邦彦","dynasty":"宋","verses":["沙棠舟。","小棹游。","池水澄澄人影浮。","锦鳞迟上钩。","烟云愁。","箫鼓休。","再得来时已变秋。","欲归须少留。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-525","tags":[]},{"id":"poem-6023ed8f23fc3a6809c884ee","title":"鹧鸪天·肥水东流无尽期","author":"姜夔","dynasty":"宋","verses":["肥水东流无尽期。","当初不合种相思。","梦中未比丹青见，暗里忽惊山鸟啼。","春未绿，鬓先丝。","人间别久不成悲。","谁教岁岁红莲夜，两处沈吟各自知。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-122","tags":["宋词三百首"]},{"id":"poem-6028e8a5370285f98a7c105e","title":"满庭芳·初绾云鬟","author":"黄庭坚","dynasty":"宋","verses":["初绾云鬟，才胜罗绮，便嫌柳陌花街。","占春才子，容易托行媒。","其奈风情债负，烟花部、不免差排。","刘郎恨，桃花片片，随水染尘埃。","风流，贤太守，能笼翠羽，宜醉金钗。","且留取垂杨，掩映厅阶。","直待朱轓去后，从伊便、窄袜弓鞋。","知恩否，朝云暮雨，还向梦中来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-651","tags":[]},{"id":"poem-603fc15f796660796ef9c605","title":"偈颂（幷序○序为南岳齐己撰） 九十二","author":"居遁","dynasty":"唐","verses":["若能明实相，岂用陈知见。","一念了自心，开佛诸知见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fa8c2f89-7891-42a1-89e7-5b1ed2d95cce","tags":["衡山"]},{"id":"poem-6043905e571e0ebf0b8d723e","title":"送僧归华山","author":"贯休","dynasty":"唐","verses":["心枯衲亦枯，归岳揭空盂。","七贵留不住，孤云出更孤。","烧灰犹汤足，雪片似黏须。","他日如相觅，还应道到吴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ed50c044-aa14-4cee-a88e-de5772498fd1","tags":[]},{"id":"poem-6043a4402bfc09971407d0a7","title":"送程秀才","author":"司空曙","dynasty":"唐","verses":["悠悠多路岐，相见又别离。","东风催节换，燄燄春阳散。","楚草渐烟绵，江云亦芜漫。","送子恨何穷，故关如梦中。","游人尽还北，旅雁辞南国。","枫树几回青，逐臣归不得。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d2454276-7690-4f8a-8a84-f594d3856f05","tags":[]},{"id":"poem-604e812a5c134b99ce921f24","title":"送同落第者东归","author":"李益","dynasty":"唐","verses":["东门有行客，落日满前山。","圣代谁知者，沧洲今独还。","片云归海暮，流水背城闲。","余亦依嵩颍，松花深闭关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b4ed9dbf-ff4b-49ee-b3bd-6d621c5f5766","tags":[]},{"id":"poem-6057033565a207cc1d345e57","title":"和陶渊明二十首  其一○","author":"陈造","dynasty":"宋","verses":["自公有至乐，诗卷还坐隅。","得句一吐之，嬉然忘穷涂。","百世一俯仰，万象付驰驱。","吟情当饮兴，其乐皆有余。","役心声利场，咄咄彼何居。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-710c1b7f-6ff2-46bd-987c-f58f4102e05d","tags":[]},{"id":"poem-6060a260533f50d606f9c4dd","title":"念奴娇·断虹霁雨","author":"黄庭坚","dynasty":"宋","verses":["断虹霁雨，净秋空，山染修眉新绿。","桂影扶疏，谁便道，今夕清辉不足。","万里青天，姮娥何处，驾此一轮玉。","寒光零乱，为谁遍照醽醁。","年少从我追游，晚凉幽径，绕张园森木。","共倒金荷家万里，难得尊前相属。","老子平生，江南江北，最爱临风曲。","孙郎微笑，坐来声喷霜竹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-648","tags":[]},{"id":"poem-607931cc4da67a58006e4a86","title":"庄陵挽歌词三首 三","author":"张籍","dynasty":"唐","verses":["晓日龙车动，秋风阊阖开。","行帷六宫出，执绋万方来。","惨惨郊原暮，迟迟挽唱哀。","空山烟雨夕，新陌遶陵台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-739d2637-932f-4ef4-9ce8-63506681e838","tags":[]},{"id":"poem-607d33e04cbddc10ec26a58e","title":"游山呈景仁","author":"司马光","dynasty":"宋","verses":["我禄多龚舍，君年少孔戣。","道心闲始见，世路老方知。","山水不相厌，风光难豫期。","嬉游不可缓，花卉即离披。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b3e769d5-3c56-42dc-8b70-266a5b70e775","tags":[]},{"id":"poem-60851876c75b0f932b664eae","title":"送王贞白重试东归","author":"贯休","dynasty":"唐","verses":["心苦酬心了，东归谢所知。","可邻重试者，如折两三枝。","雨毒逢花少，山多爱马迟。","此行三可羡，正值倒戈时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d7ecbd4c-aa8d-42a8-ab02-e79733151163","tags":[]},{"id":"poem-60882777d8e60a1a81991861","title":"渔家傲·折柳赠君君且住","author":"程师孟","dynasty":"宋","verses":["折柳赠君君且住。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-959","tags":[]},{"id":"poem-6088c10ff781f7f061eb92fe","title":"奉使登终南山","author":"王湾","dynasty":"唐","verses":["常爱南山游，因而尽原隰。","数朝至林岭，百仞登嵬岌。","石壮马径穷，苔色步缘入。","物奇春状改，气远天香集。","虚洞策杖鸣，低云拂衣湿。","倚岩见庐舍，入户欣拜揖。","问性矜勤劳，示心教澄习。","玉英时共饭，芝草为余拾。","境绝人不行，潭深鸟空立。","一乘从此授，九转兼是给。","辞处若轻飞，憩来唯吐吸。","闲襟超已胜，回路倏而及。","烟色松上深，水流山下急。","渐平逢车骑，向晚睨城邑。","峰在野趣繁，尘飘宦情澁。","辛苦久为吏，劳生何妄执。","日暮怀此山，悠然赋斯什。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e4c75dc6-6c7d-4141-a878-7d8786d4bebb","tags":["终南山"]},{"id":"poem-609684d341a6580b8bc8e97f","title":"村居","author":"林之奇","dynasty":"宋","verses":["日影满松窗，云开雨初止。","晴林梨栗熟，晓巷儿童喜。","牛羊深涧下，凫雁寒塘里。","田父酒新成，瓶瓮馈邻里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a24d8b39-ce77-4bbb-b7b3-b4804479ae80","tags":[]},{"id":"poem-6099df3edbd1ca0acdb9a955","title":"蓦山溪·画桥流水","author":"贺铸","dynasty":"宋","verses":["画桥流水，宛是南州路。","转柁绿杨湾，恍然间、青楼旧处。","回肠断尽，犹剩尔多愁，记新声，怀昵语。","依约对眉宇。","袜罗香在，祗欠莲随步。","无物比朝云，恨难续、高唐后赋。","迢遥此夜，泪枕不成眠，月侵窗，灯映户。","应见可怜许。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-81","tags":[]},{"id":"poem-609a5de561cc9ed7283aebff","title":"哭微之","author":"白居易","dynasty":"唐","verses":["今在岂有相逢日，未死应无暂忘时。","从此三篇收泪后，终身无复更吟诗。","（见《文苑英华》。","）（按《全唐诗》载《哭微之》诗二首，其诗原附于白居易《祭微之文》，畧谓无以寄悲情，作哀词二首云云。","《全唐文》卷六百八十一及坊刻《白香山集》均载之。","惟《文苑英华》卷九百八十九《祭微之文》则谓作哀词三首，其第三首为）（诸本所无。","承友人顾学颉先生函告，爰补录于此。","或以其出处不明为疑，则俟方家之考定于来更可耳。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-33b2fbcb-28b9-4794-a22d-08b8e7bd4c10","tags":[]},{"id":"poem-60af844b37c1561bc1e66207","title":"满江红·手摘桐花","author":"吴泳","dynasty":"宋","verses":["手摘桐花，怅还是、春风婪尾。","按锦瑟、一弦一柱，又添一岁。","紫马西来疑是梦，朱衣双引浑如醉。","较香山、七十欠三年，吾衰矣。","红袖却，青尊止。","檀板住，琼杯废。","淡香凝一室，自观生意。","事业不堪霜满镜，文章底用花如绮。","笑江滨、游女尚高歌，滕王记。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-574","tags":[]},{"id":"poem-60ba1aab582c841b79700b40","title":"病起四诗 一节食","author":"陈造","dynasty":"宋","verses":["医经戒多食，书恶殄天物。","细茹取微足，卫生此其术。","是铭当匕筯，况我已衰疾。","胡为冒所戒，一卧复十日。","恙疴不虚生，一一自口实。","大嚼健武事，欲强蒲柳质。","行年逾知命，备历世纤悉。","山肤与水豢，尝味几十七。","婪酣复不已，颐正昧终吉。","昔人议四凶，饕餮乃其一。","不见辟谷翁，曾是汉良弼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7c69fe26-8621-4700-869d-6019a12a0a70","tags":[]},{"id":"poem-60bedf4a35466500e9ba73bf","title":"送唐介南迁  其五","author":"谢景初","dynasty":"宋","verses":["谏逐古今有，例为朝政疵。","况与廊庙臣，世复恶其私。","安危治乱迹，此事姑置之。","傥未监谤者，失得何须悲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4d77dcb3-40ef-4817-bd67-01f4d449753d","tags":[]},{"id":"poem-60c3acae00e2f738240ec9ed","title":"感寓二首 一","author":"梁德裕","dynasty":"唐","verses":["彩云呈瑞质，五色发人寰。","独作龙虎状，孤飞天地间。","隐隐临北极，峨峨象南山。","恨在帝乡外，不逢枝叶攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-12ae270e-cab4-4a34-b9a1-0aaa66c16f98","tags":[]},{"id":"poem-60c9073993f69c304e85ac97","title":"狂题十八首 十五","author":"司空图","dynasty":"唐","verses":["昨日流莺今日蝉，起来又是夕阳天。","六龙飞辔长相窘，更忍乘危自着鞭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2926ddf8-9d99-4c0a-87c9-56db60e5cb75","tags":[]},{"id":"poem-60d3e1a690e030435b34412b","title":"逢故人之作","author":"佚名","dynasty":"唐","verses":["故人相见汾酒龙钟，总为情怀昔日浓。","随头尽见新白髪，何曾有个旧颜容！。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-dbdffc1e-d6ae-4d78-8b66-760fb8b0149a","tags":[]},{"id":"poem-60d4a7c65fd479632da67d92","title":"九日陪颜使君真卿登水楼","author":"皎然","dynasty":"唐","verses":["重阳荆楚尚，高会此难陪。","偶见登龙客，同游戏马台。","风文向水叠，云态拥歌回。","持菊烦相问，扪襟媿不才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-039f75f6-1973-49c0-9e88-35f0b4882d4f","tags":[]},{"id":"poem-60da0e157e7ada223add12fe","title":"甘露寺东轩","author":"周繇","dynasty":"唐","verses":["每日怜晴眺，闲吟只自娱。","山从平地有，水到远天无。","老树多封楚，轻烟暗染吴。","虽居此廊下，入户亦踌蹰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-18de435e-9774-4859-827c-0bcf1d6532ea","tags":[]},{"id":"poem-60e00a087651405324f19334","title":"竹枝·乱绳千结绊人深","author":"孙光宪","dynasty":"五代","verses":["乱绳千结（竹枝）绊人深（女儿），越罗万丈（竹枝）表长寻（女儿）。","杨柳在身（竹枝）垂意绪（女儿），藕花落尽（竹枝）见莲心（女儿）。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-34","tags":[]},{"id":"poem-60ee227a3163424b7ab80c78","title":"驾幸长安奉使先往检察","author":"王无竞","dynasty":"唐","verses":["奉使至京邑，戒涂历险夷。","首旬发定鼎[一]，再信过灞池。","河山壮关辅，金火递雄雌。","文物沦霸运，灵符启圣青。","宸扆阔临御，巡幸顺讴思。","城阙生光彩，草树含荣滋。","缇绮（骑）[二]纷沓袭，翠旗曳葳蕤。","童幼闻明主，耆老感盛仪。","轮袂交隐隐，廛陌满熙熙。","微臣昧所识，观俗书此词。","（[一]刘云：「定鼎见《左传》，成王定鼎于郏鄏，此处用以代表洛阳。","又考唐代洛阳城郭南而第二门名定鼎门，为西行必由门户。","」[二]依刘校。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1d8e4563-8ca8-4e04-8e20-3c447be67061","tags":[]},{"id":"poem-60f8d1cf8b89cc7a252ce2ab","title":"陆川道中偶成","author":"李纲","dynasty":"宋","verses":["峤南江北本来同，往返纷纷一梦中。","旧事销磨那复有，新愁缭绕亦成空。","天边山色浮浓翠，溪上云光拂淡红。","我把浮生如梦看，云山元是小屏风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1c3330c0-dd1c-48fc-a26d-4b28b0ed50a9","tags":[]},{"id":"poem-60f8fb6eba853bab02abc0b5","title":"寓意漫成","author":"蔡必荐","dynasty":"宋","verses":["东邻老翁富钜万，每日关门常独饭。","西邻少年居钱不满百，每日开筵延上客。","老翁回头问少年，君家宾客何骈阗。","少年答曰翁不知，人生许得几何时。","翁看日月如流水，牢锁黄金与阿谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8d00681c-6b3f-4fdc-ae44-35004dd30140","tags":[]},{"id":"poem-6100c40cb0f20c78100da195","title":"惜春郎·玉肌琼艳新妆饰","author":"柳永","dynasty":"宋","verses":["玉肌琼艳新妆饰。","好壮观歌席。","潘妃宝钏，阿娇金屋，应也消得。","属和新词多俊格。","敢共我勍敌。","恨少年、枉费疏狂，不早与伊相识。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-87","tags":[]},{"id":"poem-610c2088d82875bcf71b1b6e","title":"浣溪沙·庭菊飘黄玉露浓","author":"顾敻","dynasty":"五代","verses":["庭菊飘黄玉露浓，冷莎偎砌隐鸣蛩，何期良夜得相逢。","背帐风摇红蜡滴，惹香梦暖绣衾重，觉来枕上怯晨钟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-4","tags":[]},{"id":"poem-610e5e5fd276973bc1ef64ec","title":"和袁郎中破贼后经剡县山水上太尉","author":"李嘉祐","dynasty":"唐","verses":["受律仙郎贵，长驱下会稽。","鸣笳山月晓，摇斾野云低。","翦寇人皆贺，回军马自嘶。","地闲春草绿，城静夜乌啼。","破竹清闽岭，看花入剡溪。","元戎催献捷，莫道事攀跻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2d233eb4-3770-4ebd-abaf-7e54728db062","tags":[]},{"id":"poem-611496b7bc0acdabf9399f1d","title":"春秋战国门 鬻拳","author":"周昙","dynasty":"唐","verses":["鬻拳强谏惧威刑，退省怀慙不顾生。","双刖忍行留痛恨，惟君适足见忠诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6374d5f0-f329-4686-bb3c-bcd4cd9e99cb","tags":[]},{"id":"poem-61150cd09a5f4c797a20a856","title":"闵予小子","author":"佚名","dynasty":"先秦","verses":["闵予小子，遭家不造，嬛嬛在疚。于乎皇考，永世克孝。","念兹皇祖，陟降庭止。维予小子，夙夜敬止。于乎皇王，继序思不忘。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-285","tags":[]},{"id":"poem-611620c11d0fd6b962d15a6b","title":"喜秋风","author":"杨景贤","dynasty":"元","verses":["珠泪垂，柔肠结，两眉攒，寸心裂。","好儿女似花开谢，早相离半月。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10324","tags":[]},{"id":"poem-61189443ea464d71643a51ce","title":"省题诗二十一首 风中琴","author":"王棨","dynasty":"唐","verses":["虚簷来晓吹，横榻有瑶琴。","暗报青苹叶，潜生绿绮音。","数声随籁去，余响人堂深。","徽假大王按，弦因少女吟。","如筝飘阁上，似瑟鼓江浔。","若与钟期会，还知天地心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b5974bad-6e41-46b1-a46c-0be2ce8c71f3","tags":[]},{"id":"poem-612e01c5112796bd1b0b80d0","title":"浣溪沙·菱藕花开来路香","author":"方千里","dynasty":"宋","verses":["菱藕花开来路香。","满船丝竹载西凉。","波摇发彩粉生光。","翡翠双飞寻密浦，鸳鸯浓睡倚回塘。","闲情须与酒商量。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-519","tags":[]},{"id":"poem-6131051f445cb01f04fded27","title":"桂林叹鴈","author":"李渤","dynasty":"唐","verses":["三朝四黜倦遐征，往复皆愁万里程。","尔解分飞却回去，我方从此向南行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-770594bc-7922-4ac1-b7b6-38f972d20ae1","tags":[]},{"id":"poem-61375e82fc612fe157cb4999","title":"题义门胡氏华林书院","author":"宋琪","dynasty":"宋","verses":["贤良肄业文方盛，孝友传家族更豪。","旌表特恩门第贵，御书新赐姓名高。","谋孙有后荣非数，待士无疏众岂劳。","我想华林终未到，只因气概属仙曹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0e22a40a-4f5a-4da4-8ff4-7483b8142099","tags":[]},{"id":"poem-613cdfe2c966d0adb530a3e2","title":"玉树曲","author":"释居简","dynasty":"宋","verses":["翠袖薄，霞裾飘，盈盈不动金步摇。","步摇金扶翠翘玉，只知今夕欢难足，不知明日欢难续。","瑶姬自是能吟女，璧合知还旧躔度。","古菱花试小龙文，双鸾舞处亭亭分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1c1687b8-8e59-41a2-bc53-b87f36c2b192","tags":[]},{"id":"poem-613f915e11928952e72464f7","title":"和安国送茶","author":"张栻","dynasty":"宋","verses":["官焙苍云小卧龙，使君分饷自题封。","打门惊起曲肱梦，公案从今又一重。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2b04c7f3-d814-44f8-8a59-905d21b6e5de","tags":[]},{"id":"poem-61406b0dc8567109f90b7b47","title":"题义公禅房","author":"孟浩然","dynasty":"唐","verses":["义公习禅寂，结宇依空林。","户外一峰秀，阶前众壑深。","夕阳连雨足，空翠落庭阴。","看取莲花净，方知不染心。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題義公禪房","tags":[]},{"id":"poem-6142b1e51597cd5f7d124532","title":"虞美人·百花赶定东君去","author":"毛滂","dynasty":"宋","verses":["百花赶定东君去。","知与花何处。","阳春但更买花栽。","留住蜂儿蝶子、等君来。","翠轻绿嫩庭阴好。","醉便眠芳草。","春波如酒不曾空。","谁见东堂日日、自春风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-881","tags":[]},{"id":"poem-6153597820d2850b2942e87d","title":"惜黄花慢·送客吴皋","author":"吴文英","dynasty":"宋","verses":["送客吴皋。","正试霜夜冷，枫落长桥。","望天不尽，背城渐杳，离亭黯黯，恨水迢迢。","翠香零落红衣老，暮愁锁、残柳眉梢。","念瘦腰。","沈郎旧日，曾系兰桡。","仙人凤咽琼箫。","怅断魂送远，九辨难招。","醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。","素秋不解随船去，败红趁、一叶寒涛。","梦翠翘。","怨鸿料过南谯。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-9","tags":["宋词三百首"]},{"id":"poem-615beab2c7a1720daf0d624e","title":"直中书省","author":"白居易","dynasty":"唐","verses":["丝纶阁下文章静，钟鼓楼中刻漏长。","独坐黄昏谁是伴，紫薇花对紫薇郎。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-直中書省","tags":[]},{"id":"poem-61604ddd8b1467ed5121da1b","title":"春江曲","author":"张籍","dynasty":"唐","verses":["春江无云潮水平，蒲心出水凫雏鸣。","长干夫壻爱远行，自染春衣缝已成。","妾身生长金陵侧，去年随夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6d276f70-5659-4c8b-ae55-32fad946ad9e","tags":[]},{"id":"poem-6184552faec67b9226916047","title":"郊庙歌辞 蜡百神乐章 雍和","author":"不详","dynasty":"唐","verses":["缇籥劲序，玄英晚候。","姬蜡开仪，豳歌入奏。","蕙馥雕俎，兰芬玉酎。","大享明祇，永绥多祐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d441fe0d-554f-42aa-9e65-272f75f506e3","tags":[]},{"id":"poem-618e484c7dd9f0dda4895f9c","title":"别离情所钟十二章章四句送定叟弟之官严陵  其二","author":"张栻","dynasty":"宋","verses":["岁律亦已暮，风烈雪漫漫。","去路阻且长，念子衣裘单。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-04c3e6d5-307f-4e79-9f4c-98b46adbdc02","tags":[]},{"id":"poem-6190b339590076c43b456892","title":"谢侯彦明惠白莲栽  其一","author":"张栻","dynasty":"宋","verses":["添得湖光百亩余，湖边早已成菰蒲。","更移玉井峰头种，还有花开十丈无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4b82b866-106c-4e97-84cd-5a75d16caec2","tags":[]},{"id":"poem-619c7b1b4717aeee24cc6acb","title":"自诮","author":"张乔","dynasty":"唐","verses":["每到花时恨道穷，一生光景半成空。","只应抱璞非良玉，岂得年年不至公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c8c492ce-b641-4f65-9b0d-ef79257e63f8","tags":[]},{"id":"poem-61a896c4c99661854451b998","title":"句  其九","author":"米芾","dynasty":"宋","verses":["如来髓，释迦骨。","人不识，弥勒佛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d81c259a-6991-490c-9a62-72c8c8f8bedc","tags":[]},{"id":"poem-61ae89fe33b823cab48056ea","title":"唐多令·芦叶满汀洲","author":"刘过","dynasty":"宋","verses":["芦叶满汀洲。","塞沙带浅流。","二十年、重过南楼。","柳下系舟犹未稳，能几日、又中秋。","黄鹤断矶头。","故人今不在。","旧江山，浑是新愁。","欲买桂花同载酒，终不似、少年游。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-120","tags":["宋词三百首"]},{"id":"poem-61b2f13fb2384d26776917b5","title":"破船","author":"杜甫","dynasty":"唐","verses":["平生江海心，宿昔具扁舟。","岂惟青溪上，日傍柴门游。","苍皇避乱兵，缅邈怀旧丘。","邻人亦已非，野竹独修修。","船舷不重扣，埋没已经秋。","仰看西飞翼，下媿东逝流。","故者或可掘，新者亦易求。","所悲数奔窜，白屋难久留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-fbecdcf9-c56b-42c0-bac4-7b05f9864f2a","tags":[]},{"id":"poem-61c16e2186e17bdb106288d9","title":"村晚","author":"雷震","dynasty":"宋","verses":["草满池塘水满陂，山衔落日浸寒漪。","牧童归去横牛背，短笛无腔信口吹。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-村晚","tags":[]},{"id":"poem-61c44ce24304983076962407","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［末上］慈亲衰倦，弟兄无一人。","无人奉养，时刻常挂心。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8148","tags":[]},{"id":"poem-61cbdc3bdf7a2c93c9f14cbd","title":"越境送别者七人蒋元肃黄少度鹿伯可赵元序陈德溥叶飞卿林致约少酌驿舍","author":"王十朋","dynasty":"宋","verses":["同僚送我枫庭驿，共酌临分酒一杯。","我念泉人仍惜别，此身虽去首频回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c2f198f4-2a8c-4ba4-b2a7-0fdd76276478","tags":[]},{"id":"poem-61cdb51f6ff2d75299288704","title":"读杜紫微集","author":"崔道融","dynasty":"唐","verses":["紫微才调复知兵，长觉风雷笔下生。","还有枉抛心力处，多于五柳赋闲情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6825dad7-653d-4a02-85c0-ce50569da4bd","tags":[]},{"id":"poem-61ce4de9c1338573198676b2","title":"思文","author":"佚名","dynasty":"先秦","verses":["思文后稷，克配彼天。立我烝民，莫菲尔极。贻我来牟，帝命率育，无此疆尔界。陈常于时夏。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-274","tags":[]},{"id":"poem-61d21219b8bf6ceb9ba0a02f","title":"送好约法师归江南","author":"卢仝","dynasty":"唐","verses":["杯度度一身，法度度万民。","为报江南三二日，这回应见雪中人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8fefc1f8-1294-4635-a7c8-31354af6cace","tags":[]},{"id":"poem-61d301017bc421ef93cee364","title":"锦上花","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)你说与王老听，明日东人要上坟。","劝官人须教三省，休恁痴迷执性。","结义两无情，亲者到底只是亲。","(合)将兄弟赶出门，非亲却是亲。","仗托王公直语忠言，劝官人回转心。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1831","tags":[]},{"id":"poem-61d32c0fc0c951de0c637f49","title":"三韵三篇 二","author":"杜甫","dynasty":"唐","verses":["荡荡万斛船，影若扬白虹。","起樯必椎牛，挂席集众功。","自非风动天，莫置大水中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c2859274-fd6f-4c48-a4a5-53e1754b6aa2","tags":[]},{"id":"poem-61d3357d7f1ac1fc066992df","title":"南歌子·扑蕊添黄子","author":"温庭筠","dynasty":"唐","verses":["扑蕊添黄子，呵花满翠鬟。","鸳枕映屏山，明月三五夜，对芳颜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-41","tags":[]},{"id":"poem-61dad01ea98e22e367d4b229","title":"满庭芳·十载江湖","author":"史浩","dynasty":"宋","verses":["十载江湖，一朝簪组，宠荣曷称衰容。","圣恩不许，归卧旧庐中。","慨念东山伴侣，烟霞外、久阔仙踪。","今何幸，相逢故里，谈笑一尊同。","吾州，真幸会，湖边贺监，海上黄公。","胜渭川遗老，绛县仙翁。","纵饮何辞烂醉，脸霞转、一笑生红。","从今后，婆娑化国，千岁乐皇风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-55","tags":[]},{"id":"poem-61e8758fe2d8c6415e2554d3","title":"下第寄宣城幕中诸公","author":"赵嘏","dynasty":"唐","verses":["一醉曾将万事齐，暂陪欢去便如泥。","黄花李白墓前路，碧浪桓彝宅后溪。","九月霜中随计吏，十年江上灌春畦。","莫言春尽不惆怅，自有闲眠到日西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-add078e7-486f-4602-87d3-3e5948303cdd","tags":[]},{"id":"poem-61ef7856da9daf0d4fceed41","title":"新水令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)一从科第凤鸾飞，被奸谋有书空寄。","幸萱堂无祸危，痛兰房受岑寂。","挨不过凌逼，身沈在浪涛里。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8269","tags":[]},{"id":"poem-61f57b11e3e966b20fa93a3c","title":"与史朗中饮听黄鹤楼上吹笛","author":"李白","dynasty":"唐","verses":["一为迁客去长沙，西望长安不见家。","黄鹤楼中吹玉笛，江城五月落梅花。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-與史朗中飲聽黃鶴樓上吹笛","tags":[]},{"id":"poem-61f6a451e44b903273c20e70","title":"清平乐·孤花片叶","author":"纳兰性德","dynasty":"清","verses":["孤花片叶，断送清秋节。","寂寂绣屏香篆灭，暗里朱颜消歇。","谁怜散髻吹笙，天涯芳草关情。","懊恼隔帘幽梦，半床花月纵横。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-67","tags":[]},{"id":"poem-620184615c96458600bfa62e","title":"醋葫芦","author":"杨景贤","dynasty":"元","verses":["我问你何处是家？那个是亲？几年上落发做僧人？(唐僧云)出母胞胎，便做僧人。","(夫人唱)出胞胎便怎生离世尘？也是你前生有分，便是离母腹中出家，也须索有你爷娘。","与我从头一一说缘因。","(唐僧云)我父姓陈，母姓殷。","(夫人唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7961","tags":[]},{"id":"poem-620337d071fb7b94f505aff7","title":"壁间韵  其三","author":"赵崇鉘","dynasty":"宋","verses":["海棠开尽故清寒，漠漠梨花暮色闲。","酒满绿樽愁满酒，醉凭枕障认巫山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1a91e80a-4213-4d5a-bb8e-08f3f83356f4","tags":[]},{"id":"poem-621c66fd98df5ce0dc5c32c9","title":"与孟郊洛北野泉上煎茶","author":"刘言史","dynasty":"唐","verses":["粉细越笋芽，野煎寒溪滨。","恐乖灵草性，触事皆手亲。","敲石取鲜火，撇泉避腥鳞。","荧荧爨风铛，拾得坠巢薪。","洁色既爽别，浮氲亦慇懃。","以兹委曲静，求得正味真。","宛如摘山时，自歠指下春。","湘瓷泛轻花，涤尽昏渴神。","此游惬醒趣，可以话高人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-26f085ee-d6b5-4461-9197-8ada7ead97fe","tags":[]},{"id":"poem-621c751aaaf4fc54d0bc305f","title":"又","author":"吕从庆","dynasty":"唐","verses":["隔绝羊肠已数旬，到来春霭正盈盈。","山神拟欲求新句，牵住衣裳不放行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3537b123-de58-4b25-8f3d-7314effbe8a2","tags":[]},{"id":"poem-621e0062f2c52a9e46058478","title":"同前","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["娘行听启，孩儿说与。","如今病染着身，岂是奴家推抵。","你只管苦苦，将人催逼，教奴怎地。","娘，尽教它，任取红轮坠，尤它误看的。","(末上)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-299","tags":[]},{"id":"poem-622761d591761fe6580f0770","title":"小院","author":"华镇","dynasty":"宋","verses":["小院无经过，虚庭窈深幽。","高堂昼晴永，朱箔上银钩。","文砌桐花落，碧瓦烟光流。","交疏静丹绮，飞梁架青虬。","流鶑自𪾢睆，好音暂迟留。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fd60aa29-2812-4d05-8e79-89932c82c5c6","tags":[]},{"id":"poem-622a616abc59df172637c547","title":"赠李白","author":"杜甫","dynasty":"唐","verses":["秋来相顾尚飘蓬，未就丹砂媿葛洪。","痛饮狂歌空度日，飞扬跋扈为谁雄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2fb56d01-0200-4756-88c3-e8708cc5ca44","tags":["离别","写人","生活"]},{"id":"poem-623bdf3ea05f818848965ca6","title":"寄南中友人","author":"张乔","dynasty":"唐","verses":["相梦如相见，相思去后频。","旧时行处断，华髪别来新。","浪动三湘月，烟藏五岭春。","又无归北客，书札寄何人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9b8077d3-da95-431b-b6e9-f2510303935a","tags":[]},{"id":"poem-623fc27ecb5515bbdeaa61b3","title":"维扬好·二十四桥千步柳","author":"韩琦","dynasty":"宋","verses":["二十四桥千步柳，春风十里上珠帘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-858","tags":[]},{"id":"poem-624b0ddee45967184806fbc9","title":"宿龟山次韵","author":"陈子高","dynasty":"宋","verses":["潮回浪溅细沙倾，岸柳平波映眼明。","桥接短亭连野迥，艇横长笛带风清。","迢迢翠草寒烟暝，隠隠疏林暮霭晴。","遥见叠峰清浅黛，客心伤处碧云轻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c36f5179-3c81-4afe-8cbc-62c2bd62f169","tags":[]},{"id":"poem-624f74ca354d3e29a0eae536","title":"龙池寺望月寄韦使君阎别驾","author":"司空曙","dynasty":"唐","verses":["清光此夜中，万古望应同。","当野山沈雾，低城树有风。","花宫纷共邃，水府皓相空。","遥想高楼上，唯君对庾公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-648d56c4-71c8-4613-96bb-c1a7e960c20b","tags":[]},{"id":"poem-6252c9ae018a364f493a3023","title":"良耜","author":"佚名","dynasty":"先秦","verses":["畟畟良耜，俶载南亩。播厥百谷，实函斯活。或来瞻女，载筐及莒，其饟伊黍。","其笠伊纠，其镈斯赵，以薅荼蓼。荼蓼朽止，黍稷茂止。获之挃挃，积之栗栗。","其崇如墉，其比如栉。以开百室，百室盈止，妇子宁止。杀时犉牡，有捄其角。以似以续，续古之人。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-290","tags":[]},{"id":"poem-6255408ec3726ac383c3a511","title":"和尹谏议史馆山池","author":"王维","dynasty":"唐","verses":["云馆接天居，霓裳侍玉除。","春池百子外，芳树万年余。","洞有仙人箓，山藏太史书。","君恩深汉帝，且莫上空虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-91b9a8a5-a751-4edc-8d7d-9ba0ff428022","tags":[]},{"id":"poem-62576777802b38b872d2b692","title":"瀑布","author":"华镇","dynasty":"宋","verses":["苍崖入青冥，飞泉下岩顶。","薄风春雷怒，照月秋练迥。","清润冷书幌，轻柔媚茶鼎。","挥弄自忘归，赏心意谁并。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-5a21cedd-775f-4da7-bbb8-1f270850b72d","tags":[]},{"id":"poem-626e28ef368def39199b75d6","title":"临江仙·忆昔午桥桥上饮","author":"陈与义","dynasty":"宋","verses":["忆昔午桥桥上饮，坐中多是豪英。","长沟流月去无声。","杏花疏影里，吹笛到天明。","二十馀年如一梦，此身虽在堪惊。","闲登小阁看新晴。","古今多少事，渔唱起三更。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-113","tags":["宋词三百首"]},{"id":"poem-6272cb369403774702e2c10d","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］幽闲，食可加餐。","官无事扰，情怀并没愁烦。","人老花残，于心尚有相关。","待招赘百岁姻亲，承继我一脉根蔓。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8032","tags":[]},{"id":"poem-627774ef89c91d05bd622e29","title":"木兰花・玉楼春·花时人道多风雨","author":"莫将","dynasty":"宋","verses":["花时人道多风雨。","梅蕊都来无几许。","何须飘洒湿芳心，粉面琳琅如泪注。","家童莫扫花阴土。","留浥琼林枝上露。","莫教燕子早衔泥，径里馀香应满户。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-518","tags":[]},{"id":"poem-627c066df84f608e4c5686e8","title":"镜湖雪霁贻方干","author":"崔道融","dynasty":"唐","verses":["天外晓岚和雪望，月中归棹带冰行。","相逢半醉吟诗苦，应抵寒猨褭树声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3493b6cf-3c6e-449e-977f-e318c970d58e","tags":[]},{"id":"poem-62959181b6ece06b65938d52","title":"春江花月夜二首 二","author":"张子容","dynasty":"唐","verses":["交甫怜瑶珮，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b99dc5a8-4003-4bb0-9a4d-b088be0d8cb1","tags":[]},{"id":"poem-6299ab526a5bb9ef2c646c11","title":"下水船·总领神仙侣","author":"黄庭坚","dynasty":"宋","verses":["总领神仙侣。","齐到青云歧路。","丹禁风微，咫尺谛闻天语。","尽荣遇。","看即如龙变化，一掷灵梭风雨。","真游处。","上苑寻春去。","芳草芊芊迎步。","几曲笙歌，樱桃艳里欢聚。","瑶觞举。","回祝尧龄万万，端的君恩难负。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-809","tags":[]},{"id":"poem-62a10cad2c145f456fd0ce2b","title":"恭禧皇太后挽歌词三首 二","author":"薛能","dynasty":"唐","verses":["月落娥兼隐，宫空后岂还。","衔哀穷地界，亲莅泣天颜。","旧住留丹药，新陵在碧山。","国人伤莫及，应只咏关关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-45c6e213-cc43-4c89-a21e-95f3a90fcb7e","tags":[]},{"id":"poem-62a6e890062da49b3307cf8d","title":"小游仙诗九十八首 十八","author":"曹唐","dynasty":"唐","verses":["洞里烟霞无歇时，洞中天地足金芝。","月明朗朗溪头树，白发老人相对棋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-698e79de-d181-44ba-b407-a875130650af","tags":[]},{"id":"poem-62a6f22cbb810fb0d75cecca","title":"出峡","author":"李纲","dynasty":"宋","verses":["出峡日将暮，绮霞连水明。","山遥欣野阔，海近觉江平。","稍稍洲渚转，霏霏烟霭生。","舟人喜风便，时发櫂讴声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a92150e1-c280-484d-a719-b132f47b66d8","tags":[]},{"id":"poem-62b45ea7b894e14e97d997a2","title":"更漏子·南浦情","author":"牛峤","dynasty":"五代","verses":["南浦情，红粉泪，怎奈两人深意。","低翠黛，卷征衣，马嘶霜叶飞。","招手别，寸肠结，还是去年时节。","书托雁，梦归家，觉来江月斜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-12","tags":[]},{"id":"poem-62b681a41925e7ba9d509324","title":"荷叶杯·一点露珠凝冷","author":"温庭筠","dynasty":"唐","verses":["一点露珠凝冷，波影。满池塘。","绿茎红艳两相乱，肠断。水风凉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-13","tags":[]},{"id":"poem-62b6fe984c14243fdbb218ce","title":"荡","author":"佚名","dynasty":"先秦","verses":["荡荡上帝，下民之辟。疾威上帝，其命多辟。","天生烝民，其命匪谌。靡不有初，鲜克有终。","文王曰咨，咨汝殷商。曾是彊御？曾是掊克？","曾是在位？曾是在服？天降滔德，女兴是力。","文王曰咨，咨女殷商。而秉义类，彊御多怼。","流言以对。寇攘式内。侯作侯祝，靡届靡究。","文王曰咨，咨女殷商。女炰烋于中国。敛怨以为德。","不明尔德，时无背无侧。尔德不明，以无陪无卿。","文王曰咨，咨女殷商。天不湎尔以酒，不义从式。","既衍尔止。靡明靡晦。式号式呼。俾昼作夜。","文王曰咨，咨女殷商。如蜩如螗，如沸如羹。","小大近丧，人尚乎由行。内奰于中国，覃及鬼方。","文王曰咨，咨女殷商。匪上帝不时，殷不用旧。","虽无老成人，尚有典刑。曾是莫听，大命以倾。","文王曰咨，咨女殷商。人亦有言：颠沛之揭，枝叶未有害，本实先拨。殷鉴不远，在夏后之世。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-254","tags":[]},{"id":"poem-62b79db33dcf2d2ff1856eaa","title":"句","author":"樊晃","dynasty":"唐","verses":["巧裁蝉鬓畏风吹，尽作蛾眉恐人妒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8928ce05-1d1d-4a58-a334-f4f8b624e6b8","tags":[]},{"id":"poem-62b959fc04c3f65cc386e82b","title":"偈颂（幷序○序为南岳齐己撰） 五十一","author":"居遁","dynasty":"唐","verses":["成佛人稀念佛多，念来岁久却成魔。","君今欲得易（《传灯录》作「自」）成佛，无念之心（《传灯录》作「人」）不较多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-944e4d92-7594-4579-9e10-a7e5cbf28bc4","tags":["衡山"]},{"id":"poem-62bcff8eca00733c4f91e365","title":"观潮十韵","author":"张祜","dynasty":"唐","verses":["泯泯顺为回，泙泙逆是来。","草微淹泽莽，沙涨积云堆。","不止灵威怒，当慿恠力推。","夏天江叠雪，晴日海奔雷。","近落痕犹浅，初平势渐开。","舟惊浮浩渺，石看打崔嵬。","鸟下愁滩没，人行畏岸颓。","鼓风连涵澹，值洑更旋回。","进退随蟾魄，虚盈合蚌胎。","何妨俾巨浸，为尔济川才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1b7490fe-c3d2-4907-837a-0c8b5e83befd","tags":["钱塘江"]},{"id":"poem-62c838ec68feb195574fcef4","title":"题天台山石桥庵院","author":"綦崇礼","dynasty":"宋","verses":["林麓阴森径屈盘，渐惊危步入重峦。","地分宝刹临空翠，天设飞梁跨激湍。","雾暗云蒸山气肃，雪翻雷辊水声寒。","我来不作多求想，试出神光变现看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-abf2d5b8-419d-4d53-a715-03d63054b7ce","tags":[]},{"id":"poem-62cc7b3bb212ea014f27198d","title":"洛阳道","author":"储光羲","dynasty":"唐","verses":["大道直如发，春来佳气多。","五陵贵公子，双双呜玉珂。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-洛陽道","tags":[]},{"id":"poem-62d4fd32467ae83509153e70","title":"挽敖仪仲  其三","author":"刘翼","dynasty":"宋","verses":["昼倚篮舆饯一杯，殷勤别语到帘帏。","那知此夜成长往，书屋无人月掩扉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9ce2e3c1-c3ed-4664-9eb1-ee5e9b69690d","tags":[]},{"id":"poem-62df361e219e761d67ded4b5","title":"浣溪沙·谁念西风独自凉","author":"纳兰性德","dynasty":"清","verses":["谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳。","被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-8","tags":[]},{"id":"poem-62e52c2924028d57ea39a0f7","title":"九怀·尊嘉","author":"王褒","dynasty":"汉","verses":["季春兮阳阳，列草兮成行。","余悲兮兰生，委积兮从横。","江离兮遗捐，辛夷兮挤臧。","伊思兮往古，亦多兮遭殃。","伍胥兮浮江，屈子兮沉湘。","运余兮念兹，心内兮怀伤。","望淮兮沛沛，滨流兮则逝。","榜舫兮下流，东注兮磕磕。","蛟龙兮导引，文鱼兮上濑。","抽蒲兮陈坐，援芙蕖兮为盖。","水跃兮余旌，继以兮微蔡。","云旗兮电骛，倏忽兮容裔。","河伯兮开门，迎余兮欢欣。","顾念兮旧都，怀恨兮艰难。","窃哀兮浮萍，泛淫兮无根。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-42","tags":[]},{"id":"poem-62e9b942ca43fe98268daad0","title":"河梁晚望二首 一","author":"子兰","dynasty":"唐","verses":["水势滔滔不可量，渔舟容易泛沧浪。","连山翠霭笼沙溆，白鸟翩翩下夕阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-588ebca2-06d2-4477-9a92-2191593a4abd","tags":[]},{"id":"poem-62ec049de08298beba5bcf2e","title":"范真传侍御累有寄因奉酬十首 五","author":"鲍溶","dynasty":"唐","verses":["闻道中山酒，一杯千日醒。","黄莺似传语，劝酒太叮咛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-83e0373b-c0ca-429b-a44b-595d9dcd8002","tags":[]},{"id":"poem-62ee2e52605ae608cf8cc26c","title":"游囊山","author":"黄滔","dynasty":"唐","verses":["山有重嚢势，门开两径斜。","溪声寒走涧，海色月流沙。","庵外曾游虎，堂中旧雨花。","不知遗谶地，一一落谁家？","（见黄鸣乔刻本《黄御史集》卷二。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8cd8ac9f-ae9c-42ae-90e9-d5af21a0ce40","tags":[]},{"id":"poem-62f85ed77829022703c87920","title":"陪游上苑遇雪","author":"萧至忠","dynasty":"唐","verses":["龙骖晓入望春宫，正逢春雪舞春风。","花光倂在天文上，寒气行销御酒中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a39ebbbd-8626-4de4-a582-23146a31e189","tags":[]},{"id":"poem-630839f4e9c3dfe98b38d4b9","title":"轮台歌奉送封大夫出师西征","author":"岑参","dynasty":"唐","verses":["轮台城头夜吹角，轮台城北旄头落。","羽书昨夜过渠黎，单于已在金山西。","戍楼西望烟尘黑，汉兵屯在轮台北。","上将拥旄西出征，平明吹笛大军行。","四边伐鼓雪海涌，三军大呼阴山动。","虏塞兵气连云屯，战场白骨缠草根。","劒河风急雪片阔，沙口石冻马蹄脱。","亚相勤王甘苦辛，誓将报主静边尘。","古来青史谁不见，今见功名胜古人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d129dc0f-cec9-4073-bb89-cb9312564d9d","tags":["唐诗三百首","战争","生活","七言古诗","赞扬","边塞","将士"]},{"id":"poem-630eaa528998e869693f5732","title":"曲江二首 一","author":"李山甫","dynasty":"唐","verses":["南山低对紫云楼，翠影红阴瑞气浮。","一种是春长富贵，大都为水也风流。","争攀柳带千千手，间插花枝万万头。","独向江边最惆怅，满衣尘土避王侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2a81130f-f5d8-42cb-aa0e-aed0adec9531","tags":[]},{"id":"poem-631552fc7ba4049eb9911849","title":"赏春","author":"路半千","dynasty":"唐","verses":["暖日当头催展菜，和风次第遣开花。","呼童远取溪心水，待客来煎柳眼茶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-53dc188c-b67b-4e38-a59d-667eca3b351a","tags":[]},{"id":"poem-631b7dd6a1239c86c667bb6e","title":"菩萨蛮·催花未歇花奴鼓","author":"纳兰性德","dynasty":"清","verses":["催花未歇花奴鼓，酒醒已见残红舞。","不忍覆余觞，临风泪数行。","粉香看又别，空剩当时月。","月也异当时，凄清照鬓丝。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-182","tags":[]},{"id":"poem-631d14881981d9426edfb2dc","title":"同崔兴宗送衡岳瑗公南归","author":"王维","dynasty":"唐","verses":["言从石菌阁，新下穆陵关。","独向池阳去，白云留故山。","绽衣秋日里，洗钵古松间。","一施传心法，唯将戒定还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-709fec89-040a-4bd4-bded-75c329c91dce","tags":[]},{"id":"poem-631e1f1fe437b40b00aa482a","title":"采桑子·梦一场","author":"纳兰性德","dynasty":"清","verses":["谢家庭院残更立，燕宿雕梁。","月度银墙，不辨花丛哪瓣香。","此情已自成追忆，零落鸳鸯。","雨歇微凉，十一年前梦一场！"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-46","tags":[]},{"id":"poem-631fcd957722152a30f9dc36","title":"古塞下曲四首 三","author":"贯休","dynasty":"唐","verses":["日向平沙出，还向平沙没。","飞蓬落军营，惊雕去天末。","帝乡青楼倚霄汉，歌吹掀天对花月。","岂知塞上望乡人，日日双眸滴清血。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1a9cd899-f5d3-4dfa-9d3d-27f1782942e9","tags":[]},{"id":"poem-63243e83ac9b875df0e49b52","title":"送望江张明府","author":"徐铉","dynasty":"宋","verses":["之官别是荣，诏许侍亲行。","温凊自为乐，烟波不算程。","山留丹灶室，俗有故乡情。","无使千年后，空传曲令名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7ef4b494-3df6-4db1-b96c-758f1b2b58b6","tags":[]},{"id":"poem-6325a96fdfe87170b3ec5fcc","title":"次河神庙虞参军船先发余阻风不进寒夜旅泊（斯二七一七下同）","author":"刘知几","dynasty":"唐","verses":["朝谒冯夷词（祠），夕投投孟津渚。","风长川淼漫，河阔舟容与。","回首望归途，连山暧相拒。","落帆遵逈岸，辍榜依孤屿。","复值惊彼（波）息，戒徒候前侣。","川路虽未遥，心期顿为阻。","沉沉落日暮，切切凉飚举。","白露湿寒葭，苍烟晦平楚。","啼猿响岩谷，泪鹤闻河溆。","此时怀故人，依然怆行旅。","何当欣既觏，郁陶共君敍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5c169822-fbf9-4cc0-ade4-fcb945e1a05e","tags":[]},{"id":"poem-632c43e279490a18a51f5f75","title":"出郊劝农饭蔬于法石僧舍时方闵雨有无麦之忧因成八绝  其四","author":"王十朋","dynasty":"宋","verses":["卖刀买犊慕龚遂，重谷务农思鲁僖。","僚友共怀忧国愿，守臣非皱职田眉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-347ae391-cfed-4971-8a95-348ff0d745ac","tags":[]},{"id":"poem-63355d62c43a997b9f969641","title":"村学究","author":"宋伯仁","dynasty":"宋","verses":["八九顽童一草庐，土朱勤点七言书。","晚听学长吹樵笛，国子先生殆不如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-60950620-3691-4168-b7d1-95984c575a4b","tags":[]},{"id":"poem-633cdf3cf79a18ae00df2d24","title":"点绛唇·病起恹恹","author":"韩琦","dynasty":"宋","verses":["病起恹恹，画堂花谢添憔悴。","乱红飘砌。","滴尽胭脂泪。","惆怅前春，谁向花前醉。","愁无际。","武陵回睇。","人远波空翠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-857","tags":[]},{"id":"poem-633dd8f34b041b12c9f51227","title":"浪淘沙·滩头细草接疏林","author":"皇甫松","dynasty":"唐","verses":["滩头细草接疏林，浪恶罾船半欲沉。","宿鹭眠鸥飞旧浦，去年沙嘴是江心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-18","tags":[]},{"id":"poem-633e090f860dbe994963eb14","title":"西江月","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["香径里扳残草色，雕阑畔折损花容。","又无巧艺动王公，枉费了工夫何用？惊起娇莺语燕，打开浪蝶狂烽。","若还寻得并头红，早把你芳心引动。","(净丑)打秋千耍。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4921","tags":[]},{"id":"poem-6346f8368df97a22d48fa21c","title":"秋（原作「夏」）日非所书情","author":"佚名","dynasty":"唐","verses":["自从去岁别流沙，独恨今秋归望赊。","将谓西南穷地角，谁言东北到天涯。","山河远近多穹帐，戎俗迢观少物华。","六月尚闻飞雪片，三春岂见有烟花。","凌晨倏闪奔雷电，薄暮斯须歛霁霞，傍对崇山形屹屹，前临巨壑势呀呀。","昨来覊思忧如捣，即日愁肠乱似麻。","为客已遭迍否事，不知何计得还家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-aa055b9a-c639-4113-aa9a-203e5ee55bce","tags":[]},{"id":"poem-63480f4153843b8baa9f4a9c","title":"甘露寺僧房","author":"张乔","dynasty":"唐","verses":["临水登山路，重寻旅思劳。","竹阴行处密，僧腊别来高。","远岫明寒火，危楼响夜涛。","悲秋不成寐，明月上千舠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d08e4bd5-7af6-48a0-9263-6740114e3041","tags":[]},{"id":"poem-63513620a580402b419078fe","title":"侍郎见贻佳什愈见高怀因次来章辄歌盛美  其一","author":"李昉","dynasty":"宋","verses":["望高官重两难俦，遇兴裁诗许唱酬。","鸾凤羽翰归碧落，神仙行止在丹丘。","空庭引鹤闲临水，远树惊蝉又报秋。","唯说近来都不饮，梦魂无复醉乡游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c448fae4-27d7-4054-8ac3-91e97c6e2c7d","tags":[]},{"id":"poem-6353541e0650c8018e91a396","title":"灞上送客","author":"张祜","dynasty":"唐","verses":["自省论心意不疑，五年风水因追随。","怜君有玉曾三献，顾我无才忝一枝。","烟隔灞亭人去日，雨迷秦树鴈归时。","那知此夏罇前别，却遣相如叹路歧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-db0a20c7-7a54-40c6-b0b7-4a6e8987bf97","tags":[]},{"id":"poem-635a2b1aaff8e1afe83e0789","title":"绮寮怨·上马人扶残醉","author":"周邦彦","dynasty":"宋","verses":["上马人扶残醉，晓风吹未醒。","映水曲、翠瓦朱檐，垂杨里、乍见津亭。","当时曾题败壁，蛛丝罩、淡墨苔晕青。","念去来、岁月如流，徘徊久、叹息愁思盈。","去去倦寻路程。","江陵旧事，何曾再问杨琼。","旧曲凄清。","敛愁黛、与谁听。","尊前故人如在，想念我、最关情。","何须渭城。","歌声未尽处，先泪零。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-239","tags":["宋词三百首"]},{"id":"poem-635f513f8d31a7070f361121","title":"过头陀九岭宿天王栖林二招提因成三绝  其三","author":"王十朋","dynasty":"宋","verses":["我如倦鸟欲栖林，喜见禅僧栖处深。","家在梅花小溪上，一枝聊慰北归心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e68dde16-c83e-48ac-8e40-97f918b137da","tags":[]},{"id":"poem-63674eea5c647cc042dadfe0","title":"舞曲歌辞 功成庆善乐舞词","author":"不详","dynasty":"唐","verses":["寿丘惟旧迹，酆邑乃前基。","粤余承累圣，悬弧亦在兹。","弱龄逢运改，提劒郁匡时。","指麾八荒定，怀柔万国夷。","梯山盛入欵，驾海亦来思。","单于陪武帐，日逐卫文㮰。","端扆朝四岳，无为任百司。","霜节明秋景，轻冰结水湄。","芸黄遍原隰，禾颕积京坻。","共乐还谯宴，欢此大风诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4976a8f8-250f-4373-bdb4-19222eaf4ec0","tags":[]},{"id":"poem-636819ffb1cf81e8425e0673","title":"又戴云山吟","author":"智亮","dynasty":"唐","verses":["戴云山顶白云齐，登顶方知世界低。","异草奇花人不识，一池分作九条溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-39fcc78f-7ebe-4de5-8e49-76928167f97a","tags":[]},{"id":"poem-637f07cf598f2a340136e405","title":"迷神引·黯黯青山红日暮","author":"晁补之","dynasty":"宋","verses":["黯黯青山红日暮。","浩浩大江东注。","馀霞散绮，向烟波路。","使人愁，长安远，在何处。","几点渔灯小，迷近坞。","一片客帆低，傍前浦。","暗想平生，自悔儒冠误。","觉阮途穷，归心阻。","断魂素月，一千里、伤平楚。","怪竹枝歌，声声怨，为谁苦。","猿鸟一时啼，惊岛屿。","烛暗不成眠，听津鼓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-174","tags":[]},{"id":"poem-63831fba3d7c1ad1c6653c2e","title":"郊庙歌辞 德明兴圣庙乐章 送神","author":"李舒","dynasty":"唐","verses":["元精回复，灵贶繁滋。","风洒兰路，云摇桂旗。","高丘缅邈，凉部逶迟。","瞻望靡及，缠绵永思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-db9b8092-5124-4685-8416-c092806d6bef","tags":[]},{"id":"poem-6384f648981e784734e7467d","title":"长干曲四首 二","author":"崔颢","dynasty":"唐","verses":["家临九江水，来去九江侧。","同是长干人，自小不相识。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4a732464-35a5-4ffc-94d0-37d653eef2a1","tags":["唐诗三百首","家乡","女子","热爱","乐府"]},{"id":"poem-63857a3b91368bab6210acd8","title":"青海望敦煌之作","author":"佚名","dynasty":"唐","verses":["西北指流沙，东南路转遐。","独晴留海畔，归望阻天涯。","九夏呈芳草，三时有雪花。","未能刷（原作「{帀刂}」）羽去，空此羡城鵶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d5b6f006-5259-4f22-a2f5-42580244ddb0","tags":[]},{"id":"poem-638d9fba2222f4eef89df72d","title":"春秋战国门 哀公","author":"周昙","dynasty":"唐","verses":["贤为邻用国忧危，庙算无非委艳奇。","两叶翠娥春乍展，一毛须去不难吹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bd13166f-d052-420a-bd66-12e907754e10","tags":[]},{"id":"poem-639bacdd94b052c188586c22","title":"兵要望江南 禳厌第二十四（京本作「占厌禳第十九」○十三首） 十二","author":"易静","dynasty":"唐","verses":["凡行阵，甲午甲寅（京本作「申」）旬。","甲戌都来为一处，当时（京本作「持」）刀剑在前行，其阵勒来兵。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-97ecde76-d131-4378-bdae-75b87cb5db05","tags":[]},{"id":"poem-639e6ed7f0c44b5c69231cdd","title":"常娥","author":"李商隐","dynasty":"唐","verses":["云母屏风烛影深，长河渐落晓星沈。","常娥应悔偷灵药，碧海青天夜夜心。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f7c9c409-9571-4eb8-abd9-91ec6c1ff564","tags":["唐诗三百首","孤独","中秋","写人","三年级下册","七言绝句","小学古诗"]},{"id":"poem-63a8a65fe46f948456b2b76f","title":"集灵台二首 一","author":"张祜","dynasty":"唐","verses":["日光斜照集灵台，红树花迎晓露开。","昨夜上皇新授箓，太真含笑入帘来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-19867a30-1b67-4123-b367-44565bab6516","tags":["唐诗三百首","写人","七言绝句","讽刺"]},{"id":"poem-63aaee809254541b67799bb5","title":"羯鼓","author":"崔道融","dynasty":"唐","verses":["华清宫里打撩声，供奉丝簧束手听。","寂莫銮舆斜谷里，是谁翻得雨淋铃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c0695c4d-445c-4f5e-876a-66ed7276ba7c","tags":[]},{"id":"poem-63b5235a996dee2099448e8c","title":"惜别","author":"王镃","dynasty":"宋","verses":["袂分鸳锦梦双残，一线啼痕枕未干。","门掩青灯人自去，杏花风起落花看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0ed90cdc-7991-4d31-a07f-23971c7e15eb","tags":[]},{"id":"poem-63b59e291b569fe4845f4a5e","title":"诗品二十四则 豪放","author":"司空图","dynasty":"唐","verses":["观花匪禁，吞吐大荒。","由道返气，处得以狂。","天风浪浪，海山苍苍。","真力弥满，万象在旁。","前招三辰，后引凤皇。","晓策六鼇，濯足扶桑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1e802371-0491-47f3-8981-97898b118867","tags":[]},{"id":"poem-63c4a6cffbf7209bb2f91af9","title":"河传·春暮","author":"李珣","dynasty":"五代","verses":["春暮，微雨。送君南浦，愁敛双蛾。","落花深处，啼鸟似逐离散，粉檀珠泪和。","临流更把同心结，情哽咽，后会何时节？","不堪回首，相望已隔汀洲，檐声幽。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-49","tags":[]},{"id":"poem-63c9db0bd92645c560b8d1d9","title":"郊庙歌辞 让皇帝庙乐章 奠币","author":"李舒","dynasty":"唐","verses":["惟帝时若，去而上仙。","祀用商舞，乐备宫悬。","白璧加荐，玄𫄸告虔。","子孙拜后，承兹吉蠲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-41ecef75-7b10-43ec-bd23-77fab837ced4","tags":[]},{"id":"poem-63cb40129690b98f4e64c117","title":"二","author":"王梵志","dynasty":"唐","verses":["夜眠须在后，起则每须先。","家中懃检校，衣食莫令偏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-798cf745-b669-4fb3-b0e6-4bcb02567380","tags":[]},{"id":"poem-63d67f314fe39f2b96cb0852","title":"禅师","author":"张籍","dynasty":"唐","verses":["独在西峰顶，年年闭石房。","定中无弟子，人到为焚香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9f27bad0-5a8e-45c1-ae8d-54652a436648","tags":[]},{"id":"poem-63d8c0120c6fa81e77f1cad1","title":"郊庙歌辞 五郊乐章 赤帝徵音","author":"魏征","dynasty":"唐","verses":["青阳告谢，朱明戒序。","延长是祈，敬陈椒醑。","博硕斯荐，笙镛备举。","庶尽肃恭，非馨稷黍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-17fef454-d5fd-45a0-97d8-318fb7d4bcce","tags":[]},{"id":"poem-63dfd4e557318fe5b910f9d6","title":"赠任道人","author":"张籍","dynasty":"唐","verses":["长安多病无生计，药铺医人乱索钱。","欲得定知身上事，凭君为算小行年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-41a57e93-7560-4156-8e99-d34e36ef8ade","tags":[]},{"id":"poem-63f1d516a83a4bd225a2a6a4","title":"题章野人山居","author":"马戴","dynasty":"唐","verses":["带郭茅亭诗兴饶，回看一曲倚危桥。","门前山色能深浅，壁上湖光自动摇。","闲花散落填书帙，戏鸟低飞碍柳条。","向此隐来经几载，如今已是汉家朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-43db82d6-e467-4b63-91a9-9939bee76503","tags":[]},{"id":"poem-63f2eaab514d08b1da2f1a82","title":"品令·败叶霜天晓","author":"黄庭坚","dynasty":"宋","verses":["败叶霜天晓。","渐鼓吹、催行棹。","栽成桃李未开，便解银章归报。","去取麒麟图画，要及年少。","劝公醉倒。","别语怎向醒时道。","楚山千里暮云，正锁离人情抱。","记取江州司马，坐中最老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-661","tags":[]},{"id":"poem-63f3b45f41b3c101d63e2c3c","title":"望海潮·梅英疏淡","author":"秦观","dynasty":"宋","verses":["梅英疏淡，冰澌溶泄，东风暗换年华。","金谷俊游，铜驼巷陌，新晴细履平沙。","长记误随车。","正絮翻蝶舞，芳思交加。","柳下桃蹊，乱分春色到人家。","西园夜饮鸣笳。","有华灯碍月，飞盖妨花。","兰苑未空，行人渐老，重来是事堪嗟。","烟暝酒旗斜。","但倚楼极目，时见栖鸦。","无奈归心。","暗随流水到天涯。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-66","tags":["宋词三百首"]},{"id":"poem-63f3d462c649cda92c58210d","title":"佳人","author":"杜甫","dynasty":"唐","verses":["绝代有佳人，幽居在空谷。","自云良家子，零落依草木。","关中昔丧败，兄弟遭杀戮。","官高何足论，不得收骨肉。","世情恶衰歇，万事随转烛。","夫壻轻薄儿，新人已如玉。","合昏尚知时，鸳鸯不独宿。","但见新人笑，那闻旧人哭。","在山泉水清，出山泉水浊。","侍婢卖珠回，牵萝补茅屋。","摘花不插发，采柏动盈匊。","天寒翠袖薄，日暮倚修竹。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f2db30a1-f125-44b9-a8d8-287ccb69238a","tags":["唐诗三百首","赞美","五言古诗","闺怨","女子"]},{"id":"poem-63fb99584cf2d55509fb6b8c","title":"殿试茘枝诗","author":"陈用拙","dynasty":"唐","verses":["露湿臙脂拂眼明，红袍千裹画难成。","佳人胜尽盘中味，天意偏教岭外生。","橘柚远惭登贡籍，盐梅应合共和羹。","金门若得栽培地，须占人间第一名。","（见清汪森辑《粤西诗载》卷十三）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7f780070-51f1-43c0-aed9-a07a8a21b4b7","tags":[]},{"id":"poem-6406ec7efd430cbe9fef5672","title":"酒泉子·水碧风清","author":"顾敻","dynasty":"五代","verses":["水碧风清，入槛细香红藕腻。","谢娘敛翠恨无涯，小屏斜。","堪憎荡子不还家，漫留罗带结。","帐深枕腻炷沉烟，负当年。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-13","tags":[]},{"id":"poem-64175ba7ef0a39c535aa5c25","title":"·朔风吹古柳","author":"纳兰性德","dynasty":"清","verses":["朔风吹古柳，时序忽代续。","庭草萎已尽，顾视白日速。","吾本落拓人，无为自拘束。","倜傥寄天地，樊笼非所欲。","嗟载华亭鹤，荣名反以辱。","有客叹二毛，操觚序金谷。","酒空人尽去，聚散何局促。","揽衣起长歌，明月皎如玉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-227","tags":[]},{"id":"poem-641c836da70f891993ec8d6f","title":"游子吟","author":"孟郊","dynasty":"唐","verses":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-22923091-18da-429d-9ef1-6b367fd74b1a","tags":["杂曲歌辞","唐诗三百首","乐府","母爱","三年级下册","赞颂"]},{"id":"poem-641cfdfa46ae154c8d54c4a2","title":"秦中感秋寄远上人","author":"孟浩然","dynasty":"唐","verses":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0613f575-4f07-4326-8591-603fb3d1da45","tags":["唐诗三百首","归隐","抒情","五言律诗"]},{"id":"poem-641f84c0239e1db058b7d45a","title":"奉和九日幸临渭亭登高应制得枝字","author":"韦安石","dynasty":"唐","verses":["重九开秋节，得一动宸仪。","金风飘菊蘂，玉露泫萸枝。","睿览八纮外，天文七曜披。","临深应在即，居高岂忘危。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-de75bf9f-8d29-41a6-9a03-ce01876f7971","tags":["重阳","写景","抒情","登高","重阳节"]},{"id":"poem-643a1c38eda965027a7f3fb1","title":"王昭君","author":"崔国辅","dynasty":"唐","verses":["汉使南还尽，胡中妾独存。","紫台绵望绝，秋草不堪论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2bb965aa-61a7-47be-8dab-6e3874139c7f","tags":[]},{"id":"poem-643dba44b6f96c396ab99880","title":"清平乐·阿郎去日","author":"邵某","dynasty":"宋","verses":["阿郎去日。","不道长为客。","底事桐庐无处觅。","却得广州消息。","江头一支兰船。","风雨湘妃庙前。","死恨无情江水，送郎一去三年。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-554","tags":[]},{"id":"poem-644624b3d4bfe6bd2191b7a2","title":"寿春节进","author":"贯休","dynasty":"唐","verses":["圣运关天纪，龙飞古帝基。","振摇三蜀地，耸发万年枝。","出震同中古，承干动四夷。","恩颁新命广，泪向旧朝垂。","大宝归玄谶，殊祥出远池。","法天深罔测，体圣妙难知。","俭德为全德，无思契十思。","丕图非力至，英武悉天资。","正直方亲切，回邪岂敢窥。","将排颇与牧，相得稷兼夔。","盐出符真主，麟来合大规。","赓歌随羽籥，奕叶𢽾伊祁。","寡欲情虽泰，忧民色未怡。","盛如唐创业，宛胜晋朝仪。","旰食宫莺啭，宵衣禁漏迟。","多于汤土地，还有禹胼胝。","视物如伤日，胜残去杀时。","守文情的的，无逸戒孜孜。","轩顼风重振，皇唐鼎创移。","始闻呈瑞石，又报产灵芝。","复帱高缘大，包容妙在卑。","兄呼春赫日，师指佛牟尼。","佳气宸居合，淳风乐府吹。","急贤彰帝业，解网见天慈。","粟赤千千窖，军雄万万儿。","八蛮须稽颡，四海仰昌期。","玉辇嫔嫱拥，宫花锦绣欹。","尧云同叆叇，汉祖太驱驰。","氛祲根株尽，浇讹朕兆隳。","山河方有截，野逸诏无遗。","境静消锋镝，田香熟稻𪎭。","梦中逢傅说，殿上见辛毗。","金镜悬千古，彤云起四维。","盛行唐典法，再覩舜雍熙。","祝寿干文动，郊天太一随。","煌煌还宿卫，亹亹叶声诗。","饮醴和甘雨，非烟遶御帷。","银轮随宝马，玉沼见金龟。","杳杳闻韶濩，重重降抚绥。","魏征须却出，葛亮更何之。","简约逾前古，升平美不疑。","触邪羊唅唅，鼓腹叟嘻嘻。","迈五方云大，超三始见奇。","锦霞连紫极，仙鸟下峨眉。","谢傅还为傅，周师又作师。","纳隍为永任，从谏契无为。","子子寰瀛主，孙孙日月旗。","寿春嗟寿域，万国尽虔祈。","捧日三车子，恭思八彩眉。","愿将七万岁，匍匐拜瑶墀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7cbe66fe-efd2-4132-9383-71b3e8318a1b","tags":[]},{"id":"poem-644b11a6d738bf82136fd57a","title":"春秋战国门 屈原","author":"周昙","dynasty":"唐","verses":["满朝皆醉不容醒，众浊如何拟独清。","江上流人真浪死，谁知浸润悮深诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6f30fd00-ca31-4b3e-a4c9-eccb1f0f61e2","tags":[]},{"id":"poem-644f8da581bb823be387e492","title":"风流子·细草芳南苑","author":"葛立方","dynasty":"宋","verses":["细草芳南苑，东风里、赢得一身闲。","见花朵绣田，柳丝络岸，沼冰方泮，山雪初残。","又还是，陇头春信动，梅蕊入征鞍。","月里暗香，水边疏影，淡妆宜瘦，玉骨禁寒。","泛金溪上好，开幽户、聊面翠麓云湾。","知道醉吟堪老，名利难关。","算书帏意懒，宦途游倦，旧时习气，惟有跻攀。","拟待杖藜花底，直到春阑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-528","tags":[]}];
